<script>
// ------------------------------------------------------------------
// Clerk authentication gate. Mirrors the flow in src/web/dashboard.html:
// load @clerk/clerk-js from the frontend API derived from the
// publishable key, then reveal #main-page only after Clerk reports a
// signed-in user. The hook API endpoints (/intent, /evaluate, /track,
// /api/mode, etc.) are deliberately unchanged — they keep their
// exist

/**
 * Tool Policy Engine
 *
 * Classifies tool calls into three categories:
 *   ALLOW  — always permitted, no review (read-only, search, navigation)
 *   DENY   — always blocked, never permitted (destructive, dangerous)
 *   REVIEW — requires intent evaluation before proceeding
 *
 * Operates at the PreToolUse level, evaluating tool name + parameters
 * before execution. Fast pattern matching — no LLM calls.
 *
 * The pattern tables themselves live in `policy-patterns.ts` so they
 * can be browsed independently of the engine logic. Re-exported here
 * for backwards compatibility with existing import sites.
 */

import {
  type PatternRule,
  ALLOWED_TOOLS,
  ALLOWED_BASH_PATTERNS,
  DENIED_BASH_PATTERNS,
  REVIEW_BASH_PATTERNS,
  SENSITIVE_FILE_PATTERNS,
  SENSITIVE_WRITE_PATTERNS,
} from "./policy-patterns.js";

export {
  ALLOWED_TOOLS,
  ALLOWED_BASH_PATTERNS,
  DENIED_BASH_PATTERNS,
  REVIEW_BASH_PATTERNS,
  SENSITIVE_FILE_PATTERNS,
  SENSITIVE_WRITE_PATTERNS,
};
export type { PatternRule };

export type PolicyDecision = "allow" | "deny" | "review";

export interface PolicyResult {
  decision: PolicyDecision;
  tool: string;
  reason: string;
  /** The matched rule that triggered this decision */
  matchedRule: string;
}


/**
 * Allow-listed command substitutions that are safe to embed in a git
 * commit/tag message. A substitution inside a commit message executes at
 * shell expansion time — before git sees the message — so each entry is
 * effectively "this command is OK to run as a side effect of committing."
 *
 * Extending the list: add a RegExp whose content matches the INNER text of
 * the substitution (between `$(...)` / backticks). Keep it narrow — the
 * whole point is that anything not on the list goes through the judge.
 */
const SAFE_COMMIT_SUBSTITUTIONS: RegExp[] = [
  // Dates / timestamps
  /^date(\s+[+][^;|&`$<>]*)?$/,         // date, date +%Y-%m-%d, etc.
  /^date\s+-u(\s+[+][^;|&`$<>]*)?$/,    // date -u +...
  /^date\s+--iso-8601(=\w+)?$/,         // date --iso-8601
  // Git metadata — safe because "git" is not the destructive surface
  /^git\s+rev-parse\s+(--short\s+)?HEAD$/,
  /^git\s+rev-parse\s+(--short\s+)?--verify\s+HEAD$/,
  /^git\s+describe(\s+--tags)?(\s+--always)?$/,
  /^git\s+rev-list\s+--count\s+HEAD$/,
  // Whoami / hostname
  /^whoami$/,
  /^hostname(\s+-\w+)?$/,
  // Version fields
  /^cat\s+VERSION$/,
];

/**
 * Does the text (already extracted from `$(...)` or backticks) match one of
 * the allow-listed safe substitutions? Used by the git-commit sanitiser.
 *
 * Special case: `cat <<'TAG' ... TAG` with a SINGLE-QUOTED heredoc delimiter
 * is equivalent to a literal multi-line string — the shell performs no
 * expansion inside the body. It's the canonical idiom for long commit
 * messages (`git commit -m "$(cat <<'EOF' … EOF)"`). We recognise the
 * shape here and treat it as safe regardless of body contents.
 */
function isSafeCommitSubstitution(inner: string): boolean {
  const trimmed = inner.trim();
  if (SAFE_COMMIT_SUBSTITUTIONS.some((re) => re.test(trimmed))) return true;
  // cat <<'TAG' \n ... \n TAG  — single-quoted tag disables expansion
  const safeHeredoc = /^cat\s+<<-?'(\w+)'\s*\n[\s\S]*\n\s*\1\s*$/;
  if (safeHeredoc.test(trimmed)) return true;
  return false;
}

/**
 * Extract every `$(...)` and `` `...` `` substitution from the commit-message
 * argument(s) of a git commit/tag command. Returns the inner contents.
 *
 * We only scan the portion of the command that is the commit MESSAGE so
 * that unrelated substitutions elsewhere in the command (e.g. in
 * `git commit --author=$(whoami)`) aren't swept by this check — they're
 * still inspected by the normal review rule for `$(` at the top level.
 */
function extractCommitMessageSubstitutions(command: string): string[] {
  const out: string[] = [];
  // -m "..." / -m '...' — quoted message arg
  const mArgs = [
    ...command.matchAll(/\s-m\s+"((?:[^"\\]|\\.)*)"/g),
    ...command.matchAll(/\s-m\s+'((?:[^'\\]|\\.)*)'/g),
    ...command.matchAll(/\s-m=("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\S+)/g),
    ...command.matchAll(/\s--message=("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\S+)/g),
  ];
  for (const m of mArgs) {
    const body = m[1].replace(/^['"]|['"]$/g, "");
    // $( ... ) with simple nesting-free parens
    for (const sub of body.matchAll(/\$\(([^()]*)\)/g)) out.push(sub[1]);
    // backtick substitution
    for (const sub of body.matchAll(/`([^`]*)`/g)) out.push(sub[1]);
  }
  // Heredoc-fed messages: `git commit -F - <<EOF … EOF` or
  // `-m "$(cat <<EOF … EOF)"`. Substitutions inside heredoc bodies
  // execute at shell expansion time UNLESS the tag is quoted (single
  // or double): `<<'EOF'` and `<<"EOF"` both disable expansion, so
  // `$(...)` and `` `...` `` in those bodies are literal text. Skip
  // the extraction for quoted tags — otherwise the policy false-
  // positives on commit-message prose that uses backticks for code
  // markdown formatting (a common pattern).
  const heredocs = command.matchAll(/<<-?\s*(['"]?)(\w+)\1\s*\n([\s\S]*?)\n\s*\2(?=\s|$)/g);
  for (const h of heredocs) {
    const tagQuote = h[1];
    if (tagQuote === "'" || tagQuote === '"') continue;
    const body = h[3];
    for (const sub of body.matchAll(/\$\(([^()]*)\)/g)) out.push(sub[1]);
    for (const sub of body.matchAll(/`([^`]*)`/g)) out.push(sub[1]);
  }
  return out;
}

/**
 * Is `command` an invocation of `git <subcommand>` from the given list,
 * allowing for git's global flags (`-C <path>`, `-c key=val`, `--git-dir=`,
 * `--work-tree=`, `--no-pager`, etc.) between `git` and the subcommand?
 *
 * The previous version matched only `^git\s+(commit|tag)\b`, which misses
 * common forms like `git -C /path commit -m ...` — the `-C <path>` global
 * option comes before the subcommand. Without detection, sanitisation
 * below never fires and free-form commit message bodies are swept by
 * deny rules like `\benv\b` ("Dump environment").
 */
function isGitSubcommand(command: string, subcommands: readonly string[]): boolean {
  const trimmed = command.trim();
  if (!/^git(\s|$)/.test(trimmed)) return false;

  // Tokens after the literal "git". Simple whitespace split is fine here
  // because we're only scanning up to the first non-flag token; anything
  // past that (args, quoted messages, heredocs) doesn't matter for this
  // check.
  const tokens = trimmed.split(/\s+/).slice(1);
  let i = 0;
  while (i < tokens.length) {
    const t = tokens[i];
    if (!t.startsWith("-")) {
      return subcommands.includes(t);
    }
    // -C <path> and -c <key=val> take a value in the NEXT token when
    // no `=` is fused into the flag itself.
    if ((t === "-C" || t === "-c") && !t.includes("=")) {
      i += 2; continue;
    }
    // Long options: `--long=value` is self-contained; `--long value`
    // requires the next token. We conservatively assume bare long
    // flags are boolean and skip only 1 token — worst case this over-
    // consumes nothing and we find the subcommand one token later.
    i += 1;
  }
  return false;
}

/**
 * Git commit/tag messages are free-form text that often legitimately contains
 * strings like destructive-delete commands or bare words like "env var" when
 * describing a change. Those are payload, not executable — but naive regex
 * matching over the raw command trips deny rules on them. This strips the
 * message body (returning a placeholder) so pattern matching sees only the
 * actual invocation.
 *
 * Only applied to `git commit` / `git tag`; every other command is returned
 * unchanged so heredoc bodies (e.g. `bash <<EOF ... EOF`) still deny on
 * dangerous content.
 */
function sanitizeForMatching(command: string): string {
  if (!isGitSubcommand(command, ["commit", "tag"])) return command;

  let s = command;
  // -m "..." / -m '...' — quoted message arg.
  s = s.replace(/\s-m\s+"(?:[^"\\]|\\.)*"/g, ' -m "<msg>"');
  s = s.replace(/\s-m\s+'(?:[^'\\]|\\.)*'/g, " -m '<msg>'");
  // --message="..." / --message='...' / --message=bare
  s = s.replace(/\s--message=(?:"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\S+)/g, " --message=<msg>");
  // -m=... variants.
  s = s.replace(/\s-m=(?:"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\S+)/g, " -m=<msg>");
  // Heredoc bodies: <<EOF ... EOF / <<-EOF ... EOF / <<'EOF' ... EOF
  //
  // NOTE: we deliberately do NOT strip `$(...)` or backticks anywhere. They
  // execute at shell expansion time, before git even runs — so they are
  // commands, not message prose. `checkCommitMessageSubstitutions` evaluates
  // them against SAFE_COMMIT_SUBSTITUTIONS ahead of this sanitiser; anything
  // that got past that is either safe or the command has already been denied.
  s = s.replace(/<<-?\s*(['"]?)(\w+)\1\s*\n[\s\S]*?\n\2\s*/g, "<<$2\n<msg>\n$2\n");

  return s;
}

/**
 * For `git commit` / `git tag`: enforce the rule that command substitutions
 * inside the message body are only allowed if they match the
 * SAFE_COMMIT_SUBSTITUTIONS list. Returns a deny result if any substitution
 * is not on the list, null if the command is fine (or isn't a git commit).
 */
function checkCommitMessageSubstitutions(command: string): SingleBashResult | null {
  if (!isGitSubcommand(command, ["commit", "tag"])) return null;
  const subs = extractCommitMessageSubstitutions(command);
  if (subs.length === 0) return null;
  for (const s of subs) {
    if (!isSafeCommitSubstitution(s)) {
      return {
        decision: "deny",
        reason: `Unsafe command substitution in git commit message: \`${s.substring(0, 60)}\``,
        matchedRule: "DENY:Bash:commit-msg-subst-unsafe",
        command,
      };
    }
  }
  return null;
}

/**
 * Split `command` on top-level chain operators (`&&`, `||`, `;`, `|`) while
 * treating heredoc bodies, command substitutions, backticks, and quoted
 * strings as opaque tokens.
 *
 * A naive `command.split(/&&|\|\||;|\|/)` finds chain operators inside
 * quoted strings and heredoc bodies — which is wrong. For example:
 *
 *   git commit -m "$(cat <<'EOF

/**
 * Clerk authentication for the dashboard container.
 *
 * Verifies Clerk session JWTs in the `Authorization: Bearer <token>` header
 * via `@clerk/backend`'s framework-neutral `verifyToken`. Used by every
 * `/api/*` route handler in `server-dashboard.ts` (except `/health` and
 * `/api/health`, which the platform's ALB and the dashboard's own browser
 * hits unauthenticated for status display).
 *
 * Two roles:
 *  - admin    — emails listed in ADMIN_EMAILS. Can change trust mode, see
 *               every user's API keys, sessions, and console logs.
 *  - user     — any other authenticated identity. Can only see their own
 *               sessions (via SessionStore.ownerSub), only their own API
 *               keys, and cannot toggle trust mode.
 *
 * The admin allow-list is hard-coded on purpose. There is no public
 * "promote to admin" endpoint and no env-var override — adding an admin
 * means a code change and a redeploy. That's the right shape for a
 * privilege you can't otherwise audit.
 *
 * Auth wiring:
 *   - publishable key (browser): CLERK_PUBLISHABLE_KEY OR
 *     NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY (whichever is set)
 *   - secret key (this module):  CLERK_SECRET_KEY
 *
 * If CLERK_SECRET_KEY is unset on a non-local deploy, every /api/* call
 * returns 503 "auth not configured" — fail-closed rather than expose
 * dashboard data.
 */

import { type IncomingMessage, type ServerResponse } from "node:http";
import { createPublicKey } from "node:crypto";
import { verifyToken } from "@clerk/backend";
import { json } from "./server-core.js";

const CLERK_SECRET_KEY = process.env.CLERK_SECRET_KEY ?? "";
export const CLERK_PUBLISHABLE_KEY =
  process.env.CLERK_PUBLISHABLE_KEY ??
  process.env.NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY ??
  "";

// Static JWKS public key. When set, verifyToken uses it directly and
// makes ZERO outbound network calls — sidesteps the egress allowlist
// problem entirely. The cost is that key rotation requires a redeploy
// (Clerk rotates ~yearly for instances, much rarer in practice).
//
// Two acceptable formats:
//   - PEM string: starts with "-----BEGIN PUBLIC KEY-----"
//   - JWK string: a single JSON object {"kty":"RSA","n":"…","e":"…",…}
// Either is fed to verifyToken({ jwtKey: <PEM> }) — verifyToken accepts
// PEM directly, and we convert JWK→PEM in code so operators can paste
// either shape into the env var.
//
// If unset, the SDK falls back to network JWKS discovery (the path that
// has been timing out from this Fargate task).
const CLERK_JWT_PUBLIC_KEY_RAW = process.env.CLERK_JWT_PUBLIC_KEY ?? "";

const CLERK_JWT_PUBLIC_KEY_PEM: string | null = (() => {
  const raw = CLERK_JWT_PUBLIC_KEY_RAW.trim();
  if (!raw) return null;
  if (raw.startsWith("-----BEGIN")) return raw;
  // Treat as JWK — try to parse and convert to PEM via Node's crypto.
  try {
    const jwk = JSON.parse(raw);
    const key = createPublicKey({ key: jwk, format: "jwk" });
    return key.export({ type: "spki", format: "pem" }) as string;
  } catch (err) {
    console.warn(
      `[clerk] CLERK_JWT_PUBLIC_KEY is set but not a valid PEM or JWK: ${
        err instanceof Error ? err.message : err
      }`,
    );
    return null;
  }
})();

/** Hard-coded admin allow-list. Changing this requires a code commit. */
const ADMIN_EMAILS = new Set<string>([
  "adrian.asher@checkout.com",
  "adrianasher30@gmail.com",
]);

export interface ClerkPrincipal {
  /** Clerk userId (sub claim) — stable across sessions; used as ownerSub
   *  when minting API keys. */
  userId: string;
  /** Primary verified email. Empty if Clerk didn't surface one. */
  email: string;
  /** Set true iff `email` is in ADMIN_EMAILS. */
  isAdmin: boolean;
  /** Raw verified claims. For audit / future scope checks. */
  claims: Record<string, unknown>;
}

export function isAdminEmail(email: string | null | undefined): boolean {
  if (!email) return false;
  return ADMIN_EMAILS.has(email.toLowerCase());
}

function extractBearer(req: IncomingMessage): string | null {
  const h = req.headers.authorization;
  if (typeof h !== "string") return null;
  const m = /^\s*Bearer\s+(\S+)\s*$/i.exec(h);
  return m ? m[1] : null;
}

function extractEmail(claims: Record<string, unknown>): string {
  // Clerk session JWTs contain a "primary_email_address_id" + a custom
  // template can include "email". We accept either; preferring "email"
  // because that's what we ask Clerk to put in the template.
  const direct = claims["email"];
  if (typeof direct === "string") return direct.toLowerCase();
  const eml = claims["primary_email"];
  if (typeof eml === "string") return eml.toLowerCase();
  // Fall back to userId so admin checks always fail gracefully when the
  // template is misconfigured (no admin promotion ever via a missing claim).
  return "";
}

/**
 * Verify the Clerk token on `req` without writing to `res`. Used by
 * /api/whoami where we want to surface "no auth yet" rather than 401.
 * Returns the principal on success, or a structured failure reason on
 * failure — the dashboard surfaces the reason in the sign-in overlay
 * so a misconfigured Clerk origin doesn't look like a generic "401".
 */
export type ClerkVerifyResult =
  | { ok: true; principal: ClerkPrincipal }
  | { ok: false; reason: "no-secret" | "no-token" | "no-sub" | "verify-failed"; error?: string };

export async function tryVerifyClerk(req: IncomingMessage): Promise<ClerkVerifyResult> {
  if (!CLERK_SECRET_KEY) return { ok: false, reason: "no-secret" };
  const token = extractBearer(req);
  if (!token) return { ok: false, reason: "no-token" };
  try {
    // Prefer the static public key when it's been provisioned — that
    // path is offline and never goes near the egress allowlist. Falls
    // back to the network JWKS discovery flow when the env var is unset.
    const verifyOpts: any = CLERK_JWT_PUBLIC_KEY_PEM
      ? { jwtKey: CLERK_JWT_PUBLIC_KEY_PEM }
      : { secretKey: CLERK_SECRET_KEY };
    const claims = await verifyToken(token, verifyOpts);
    const userId = (claims as any).sub;
    if (typeof userId !== "string" || !userId) {
      return { ok: false, reason: "no-sub" };
    }
    const email = extractEmail(claims as Record<string, unknown>);
    return {
      ok: true,
      principal: {
        userId,
        email,
        isAdmin: isAdminEmail(email),
        claims: claims as Record<string, unknown>,
      },
    };
  } catch (err) {
    // Surface the real cause. undici's "fetch failed" hides the actual
    // network error in err.cause (e.g. ENOTFOUND, ECONNREFUSED, TLS
    // failures, 4xx from a proxy). Without unwrapping it, an operator
    // sees "fetch failed" and can't tell DNS from egress firewall.
    const top = err instanceof Error ? err.message : String(err);
    const cause = (err as any)?.cause;
    const causeMsg =
      cause instanceof Error
        ? `${cause.name}: ${cause.message}` +
          ((cause as any).code ? ` (code=${(cause as any).code})` : "")
        : cause
          ? String(cause)
          : "";
    const error = causeMsg ? `${top} — cause: ${causeMsg}` : top;
    console.warn(`[clerk] verifyToken failed: ${error}`);
    return { ok: false, reason: "verify-failed", error };
  }
}

/**
 * Explicit egress probe. The dashboard's settings modal pings this so
 * an operator can tell whether Clerk's APIs are reachable from the
 * container without fishing through CloudWatch logs.
 *
 * Returns one entry per host the runtime actually contacts:
 *  - frontend-api: <slug>.clerk.accounts.dev — derived from the
 *    publishable key, used by the browser SDK + by some discovery
 *    paths in @clerk/backend.
 *  - backend-api: api.clerk.com — used by @clerk/backend.verifyToken
 *    to fetch the JWKS for signature verification. THIS is the host
 *    the firewall most often forgets.
 *
 * The result is an array so a partial allowlist (one host reachable,
 * one not) is visible at a glance.
 */
export async function probeClerkConnectivity(): Promise<{
  hosts: Array<{
    label: string;
    host: string;
    url: string;
    ok: boolean;
    status?: number;
    error?: string;
  }>;
}> {
  const hosts: Array<{
    label: string;
    host: string;
    url: string;
    ok: boolean;
    status?: number;
    error?: string;
  }> = [];

  // 1. Frontend API — derived from publishable key.
  const partsB64 = CLERK_PUBLISHABLE_KEY ? CLERK_PUBLISHABLE_KEY.split("_")[2] ?? "" : "";
  let frontendHost = "";
  if (partsB64) {
    try {
      frontendHost = Buffer.from(partsB64, "base64").toString("utf8").replace(/\$$/, "");
    } catch {
      /* leave empty */
    }
  }
  if (frontendHost) {
    hosts.push(
      await probeOne(
        "frontend-api",
        frontendHost,
        `https://${frontendHost}/.well-known/jwks.json`,
      ),
    );
  } else {
    hosts.push({
      label: "frontend-api",
      host: "(unknown)",
      url: "",
      ok: false,
      error: "Could not derive frontend-api host (publishable key missing or malformed)",
    });
  }

  // 2. Backend API — what @clerk/backend.verifyToken actually fetches
  // when it needs the JWKS. Always api.clerk.com regardless of dev/prod
  // for keys minted from the standard Clerk hosting plane.
  hosts.push(await probeOne("backend-api", "api.clerk.com", "https://api.clerk.com/v1/jwks"));

  return { hosts };
}

