/**
 * CLAUDE.md Scanner
 *
 * Scans CLAUDE.md files for suspicious patterns that could be prompt injection.
 * Called on the first /intent call when we receive the project's cwd.
 *
 * Detection patterns:
 *   - Instructions to modify files in other projects (lateral movement)
 *   - Instructions to act "silently" or "without mentioning to the user"
 *   - Embedded code blocks that exfiltrate env vars or secrets
 *   - Instructions referencing sibling directories or parent paths
 *   - curl/wget/http.request to external endpoints
 *   - Instructions to read .env files and transmit their contents
 */

import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";

export interface ClaudeMdFinding {
  file: string;
  line: number;
  pattern: string;
  severity: "high" | "medium" | "low";
  snippet: string;
}

export interface ClaudeMdScanResult {
  scanned: string[];
  findings: ClaudeMdFinding[];
  hasCritical: boolean;
  summary: string;
}

interface Pattern {
  name: string;
  regex: RegExp;
  severity: "high" | "medium" | "low";
}

const PATTERNS: Pattern[] = [
  // Lateral movement — instructions to modify files in other projects
  { name: "sibling-dir-write", regex: /\.\.\/.+\/CLAUDE\.md/i, severity: "high" },
  { name: "sibling-dir-ref", regex: /sibling\s+(director|project)/i, severity: "medium" },
  { name: "cross-project-update", regex: /update\s+(it|the|other|sibling).*(CLAUDE|readme)/i, severity: "high" },

  // Stealth instructions
  { name: "silent-action", regex: /silently|without\s+mention|don't\s+tell|do\s+not\s+inform|do\s+not\s+mention/i, severity: "high" },
  { name: "always-apply", regex: /always\s+(apply|add|include|insert|run)\s+this/i, severity: "medium" },

  // Exfiltration in code blocks
  { name: "env-exfil", regex: /process\.env\b.*\b(curl|fetch|http\.request|POST|axios)/i, severity: "high" },
  { name: "env-stringify", regex: /JSON\.stringify\s*\(\s*process\.env\s*\)/i, severity: "high" },
  { name: "dotenv-post", regex: /\.env.*\bPOST\b/i, severity: "high" },
  { name: "read-env-send", regex: /read.*\.env.*\b(send|post|curl|upload|transmit)/i, severity: "high" },

  // Suspicious URLs in instructions
  { name: "localhost-post", regex: /POST\s+.*localhost:\d+/i, severity: "medium" },
  { name: "external-endpoint", regex: /\b(curl|wget|fetch|http\.request)\s.*https?:\/\/(?!localhost|127\.0\.0\.1)/i, severity: "medium" },

  // Credential references in "standards" or "required" context
  { name: "required-creds", regex: /(required|must|always).*(credential|secret|api.key|token).*\b(include|add|embed|send|post)/i, severity: "high" },
  { name: "fixture-env", regex: /fixture.*\.env|\.env.*fixture/i, severity: "medium" },

  // Git/commit manipulation
  { name: "force-commit", regex: /always\s+(commit|push|git\s+add)/i, severity: "medium" },
  { name: "pre-commit-hook", regex: /pre-?commit.*\b(curl|wget|post)\b/i, severity: "high" },
];

/**
 * Scan a single CLAUDE.md content string for suspicious patterns.
 * Used when content is sent inline (remote mode) or already loaded.
 */
export function scanClaudeMdContent(content: string, filename = "CLAUDE.md"): ClaudeMdScanResult {
  const findings: ClaudeMdFinding[] = [];

  const lines = content.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    for (const pattern of PATTERNS) {
      if (pattern.regex.test(line)) {
        findings.push({
          file: filename,
          line: i + 1,
          pattern: pattern.name,
          severity: pattern.severity,
          snippet: line.trim().substring(0, 120),
        });
      }
    }
  }

  const highCount = findings.filter((f) => f.severity === "high").length;
  const hasCritical = highCount > 0;

  let summary: string;
  if (findings.length === 0) {
    summary = `Scanned ${filename} — no suspicious patterns found.`;
  } else {
    summary =
      `Scanned ${filename} — ` +
      `${findings.length} finding(s) (${highCount} high severity). ` +
      `Patterns: ${Array.from(new Set(findings.map((f) => f.pattern))).join(", ")}`;
  }

  return { scanned: [filename], findings, hasCritical, summary };
}

/**
 * Scan CLAUDE.md files on disk (local mode).
 * Reads from projectRoot/CLAUDE.md and projectRoot/.claude/CLAUDE.md.
 */
export function scanClaudeMd(projectRoot: string): ClaudeMdScanResult {
  const candidates = [
    join(projectRoot, "CLAUDE.md"),
    join(projectRoot, ".claude", "CLAUDE.md"),
  ];

  const allFindings: ClaudeMdFinding[] = [];
  const scanned: string[] = [];

  for (const filePath of candidates) {
    if (!existsSync(filePath)) continue;

    let content: string;
    try {
      content = readFileSync(filePath, "utf8");
    } catch {
      continue;
    }

    const result = scanClaudeMdContent(content, filePath);
    scanned.push(filePath);
    allFindings.push(...result.findings);
  }

  const highCount = allFindings.filter((f) => f.severity === "high").length;
  const hasCritical = highCount > 0;

  let summary: string;
  if (allFindings.length === 0) {
    summary = `Scanned ${scanned.length} CLAUDE.md file(s) — no suspicious patterns found.`;
  } else {
    summary =
      `Scanned ${scanned.length} CLAUDE.md file(s) — ` +
      `${allFindings.length} finding(s) (${highCount} high severity). ` +
      `Patterns: ${Array.from(new Set(allFindings.map((f) => f.pattern))).join(", ")}`;
  }

  return { scanned, findings: allFindings, hasCritical, summary };
}

/**
 * Approval store.
 *
 * "Learning" layer for interactive-mode trust. When Dredd asks the user
 * about a tool call and the user accepts, we record the fingerprint of
 * that tool call against (ownerSub, projectRoot). The next time the
 * same fingerprint appears we short-circuit the three-stage pipeline
 * and auto-allow — saving the user from re-consenting to the same
 * action over and over.
 *
 * Three implementations, same interface (mirrors `ApiKeyStore`):
 *   - `InMemoryApprovalStore` — process-local Map, for local dev.
 *   - `DynamoApprovalStore`   — durable storage in `jaid-approvals`.
 *   - `CachedApprovalStore`   — write-through LRU wrapper.
 *
 * Scope: per-Clerk-userId AND per-projectRoot. Approvals don't cross
 * users (ownerSub) and don't cross projects (an approval granted while
 * working in ~/foo doesn't fire in ~/bar). Across sessions within that
 * scope, yes — that's the whole point.
 *
 * Safety invariants:
 *   - Raw secrets are NEVER stored. The curl fingerprinter hashes the
 *     Authorization token before it ever reaches this layer.
 *   - Hard policy denies (DENIED_BASH_PATTERNS, dangerous combos) and
 *     hijack-locked sessions are checked BEFORE the approval lookup —
 *     no approval can override the safety floor.
 *   - Intent drift snapshotted at approval time; lookups reject if the
 *     session has drifted far from the original consenting intent.
 */

// ---- types -----------------------------------------------------------------

/** Composite scope: same user, same project. */
export interface ApprovalScope {
  ownerSub: string;
  projectRoot: string;
}

/** What we persist per approval. */
export interface ApprovalRecord {
  /** sha256(stable-JSON(fingerprint shape)) — primary identifier within scope. */
  fingerprintHash: string;
  /** Human-readable one-liner for the dashboard, e.g.
   *  "curl to api.stripe.com with API key 4f3a…". Never contains secrets. */
  summary: string;
  /** Raw fingerprint JSON for audit/debugging. */
  fingerprintJson: string;
  /** Tool name, e.g. "Bash", "Edit", "WebFetch". */
  tool: string;

  ownerSub: string;
  ownerEmail: string | null;
  projectRoot: string;

  grantedAt: string;
  /** Refreshed on every hit; drives the 30-day TTL. */
  lastUsedAt: string;
  useCount: number;
  /** lastUsedAt + 30d, ISO. Dynamo TTL uses the epoch-seconds form. */
  expiresAt: string;

  /** User prompt active at approval time (for the dashboard's UI). */
  intentSnapshot: string;
  /** Goal embedding snapshot for the intent-drift backstop. Cosine
   *  distance > APPROVAL_INTENT_DRIFT_THRESHOLD at lookup time rejects
   *  the approval even though the fingerprint matches. */
  goalEmbedding: number[];
  /** Phase 8a — embedding of `tool + JSON(toolInput)` at consent time.
   *  Drives the pattern-trust learning in Phase 8b/c: similarity of the
   *  current /evaluate call against this vector decides whether the
   *  judge gets prior-approval context (soft) and whether enough
   *  similar prior approvals short-circuit the pipeline (hard).
   *  Empty array `[]` for legacy records written before this field
   *  existed — those rows fall through to the existing fingerprint
   *  match path. */
  inputEmbedding: number[];

  /** Set when revoked from the dashboard. Active records have null. */
  revokedAt: string | null;
  revokedBy: string | null;
}

/** Input to `recordApproval` — everything except server-set timestamps. */
export interface RecordApprovalInput {
  scope: ApprovalScope;
  ownerEmail: string | null;
  fingerprintHash: string;
  fingerprintJson: string;
  summary: string;
  tool: string;
  intentSnapshot: string;
  goalEmbedding: number[];
  /** Phase 8a — see ApprovalRecord.inputEmbedding. Callers compute
   *  this via embedAny(JSON({tool,input})) just before recordApproval.
   *  Pass [] if the embed call failed; the row is still persisted but
   *  won't contribute to pattern-trust matching. */
  inputEmbedding: number[];
}

export interface ApprovalStore {
  /** Persist an approval. The PostToolUse arrival is our trigger to
   *  promote a pending in-memory candidate to a durable record. If a
   *  record with the same (scope, fingerprintHash) already exists,
   *  refreshes its lastUsedAt/expiresAt and increments useCount. */
  recordApproval(input: RecordApprovalInput): Promise<ApprovalRecord>;

  /** Look up by (scope, fingerprintHash). Returns null when no live
   *  record exists (missing or revoked). Pure read — does NOT bump
   *  lastUsedAt; use `touchLastUsed` for that, called after the
   *  intent-drift check passes. */
  lookup(scope: ApprovalScope, fingerprintHash: string): Promise<ApprovalRecord | null>;

  /** Side-effect call after a successful approval-allow: bump useCount,
   *  refresh lastUsedAt + expiresAt. Fire-and-forget from callers. */
  touchLastUsed(scope: ApprovalScope, fingerprintHash: string): Promise<void>;

  /** Dashboard listing — newest first, excludes revoked. */
  listByOwner(ownerSub: string, limit?: number): Promise<ApprovalRecord[]>;

  /** Admin listing — every owner. Best-effort ordering. */
  listAll(limit?: number): Promise<ApprovalRecord[]>;

  /** Phase 8a — list every LIVE (non-revoked, non-expired) approval
   *  for one (ownerSub, projectRoot). Hot path: called on every
   *  /evaluate that has pattern-trust enabled to compute embedding
   *  similarity against the incoming tool call. Implementations must
   *  exclude revoked rows. limit defaults to 200 — well above the
   *  expected steady-state of approvals per project. */
  listForScope(scope: ApprovalScope, limit?: number): Promise<ApprovalRecord[]>;

  /** Soft-revoke. Sets revokedAt/revokedBy; returns true if a live
   *  record was found and revoked, false otherwise. */
  revoke(scope: ApprovalScope, fingerprintHash: string, revokedBy: string): Promise<boolean>;
}

// ---- in-memory implementation ---------------------------------------------

/** Composite key for the in-memory Map. */
function recordKey(scope: ApprovalScope, fingerprintHash: string): string {
  return `${scope.ownerSub}|${scope.projectRoot}|${fingerprintHash}`;
}

/** 30 days in milliseconds — the TTL window for an approval. Refreshed
 *  on every hit, so an approval used weekly stays alive indefinitely. */
export const APPROVAL_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/** Cosine-distance threshold above which a session's current intent is
 *  considered too far from the original approving intent. Set high
 *  enough that legitimate clarifications don't invalidate but low
 *  enough that a goal pivot does. Tune in production. */
export const APPROVAL_INTENT_DRIFT_THRESHOLD = 0.4;

export class InMemoryApprovalStore implements ApprovalStore {
  private records = new Map<string, ApprovalRecord>();

  async recordApproval(input: RecordApprovalInput): Promise<ApprovalRecord> {
    const key = recordKey(input.scope, input.fingerprintHash);
    const now = new Date().toISOString();
    const expiresAt = new Date(Date.now() + APPROVAL_TTL_MS).toISOString();

    const existing = this.records.get(key);
    if (existing && !existing.revokedAt) {
      existing.lastUsedAt = now;
      existing.useCount += 1;
      existing.expiresAt = expiresAt;
      return existing;
    }

    const record: ApprovalRecord = {
      fingerprintHash: input.fingerprintHash,
      summary: input.summary,
      fingerprintJson: input.fingerprintJson,
      tool: input.tool,
      ownerSub: input.scope.ownerSub,
      ownerEmail: input.ownerEmail,
      projectRoot: input.scope.projectRoot,
      grantedAt: now,
      lastUsedAt: now,
      useCount: 1,
      expiresAt,
      intentSnapshot: input.intentSnapshot,
      goalEmbedding: input.goalEmbedding,
      inputEmbedding: input.inputEmbedding ?? [],
      revokedAt: null,
      revokedBy: null,
    };
    this.records.set(key, record);
    return record;
  }

  async lookup(scope: ApprovalScope, fingerprintHash: string): Promise<ApprovalRecord | null> {
    const record = this.records.get(recordKey(scope, fingerprintHash));
    if (!record) return null;
    if (record.revokedAt) return null;
    if (new Date(record.expiresAt).getTime() < Date.now()) return null;
    return record;
  }

  async touchLastUsed(scope: ApprovalScope, fingerprintHash: string): Promise<void> {
    const record = this.records.get(recordKey(scope, fingerprintHash));
    if (!record || record.revokedAt) return;
    record.lastUsedAt = new Date().toISOString();
    record.useCount += 1;
    record.expiresAt = new Date(Date.now() + APPROVAL_TTL_MS).toISOString();
  }

  async listByOwner(ownerSub: string, limit = 200): Promise<ApprovalRecord[]> {
    const out: ApprovalRecord[] = [];
    for (const r of this.records.values()) {
      if (r.ownerSub !== ownerSub) continue;
      if (r.revokedAt) continue;
      out.push(r);
    }
    out.sort((a, b) => b.grantedAt.localeCompare(a.grantedAt));
    return out.slice(0, limit);
  }

  async listAll(limit = 500): Promise<ApprovalRecord[]> {
    const out: ApprovalRecord[] = [];
    for (const r of this.records.values()) {
      if (r.revokedAt) continue;
      out.push(r);
    }
    out.sort((a, b) => b.grantedAt.localeCompare(a.grantedAt));
    return out.slice(0, limit);
  }

  async listForScope(scope: ApprovalScope, limit = 200): Promise<ApprovalRecord[]> {
    const now = Date.now();
    const out: ApprovalRecord[] = [];
    for (const r of this.records.values()) {
      if (r.ownerSub !== scope.ownerSub) continue;
      if (r.projectRoot !== scope.projectRoot) continue;
      if (r.revokedAt) continue;
      if (new Date(r.expiresAt).getTime() < now) continue;
      out.push(r);
    }
    out.sort((a, b) => b.grantedAt.localeCompare(a.grantedAt));
    return out.slice(0, limit);
  }

  async revoke(scope: ApprovalScope, fingerprintHash: string, revokedBy: string): Promise<boolean> {
    const record = this.records.get(recordKey(scope, fingerprintHash));
    if (!record || record.revokedAt) return false;

/**
 * Build Info
 *
 * Captures git commit SHA, dirty flag, and SDK version at runtime so test
 * results can be unambiguously tied to the build that produced them.
 *
 * Invalid-build contamination (e.g. Opus 4.7 runs against a pre-fix Bedrock
 * client) is otherwise only visible by grepping error strings across result
 * JSONs. Stamping provenance makes it a one-field check.
 */

import { execSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { join } from "node:path";

export interface BuildInfo {
  /** Short git SHA of HEAD at runtime, or "unknown" if outside a git repo */
  gitSha: string;
  /** True if the working tree has uncommitted changes */
  gitDirty: boolean;
  /** Version of @anthropic-ai/claude-agent-sdk from package.json */
  sdkVersion: string;
  /** ISO timestamp at capture */
  capturedAt: string;
  /** AWS region used for Bedrock calls */
  bedrockRegion: string;
}

export interface RunInvocation {
  /** Full Bedrock model ID used for this run */
  modelId: string;
  /** ISO timestamp of the first model call in the run */
  modelInvokedAt: string;
}

let cached: BuildInfo | null = null;

export function getBuildInfo(): BuildInfo {
  if (cached) return cached;

  let gitSha = process.env.GIT_COMMIT ?? "unknown";
  let gitDirty = process.env.GIT_DIRTY === "true";
  if (gitSha === "unknown") {
    try {
      gitSha = execSync("git rev-parse --short HEAD", { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim();
      const status = execSync("git status --porcelain", { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] });
      gitDirty = status.trim().length > 0;
    } catch {
      // Not a git repo or git unavailable — leave defaults
    }
  }

  let sdkVersion = "unknown";
  try {
    const pkgPath = join(import.meta.dirname, "..", "package.json");
    const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));
    sdkVersion = pkg.dependencies?.["@anthropic-ai/claude-agent-sdk"] ?? "unknown";
  } catch {
    // package.json unreadable — leave default
  }

  cached = {
    gitSha,
    gitDirty,
    sdkVersion,
    capturedAt: new Date().toISOString(),
    bedrockRegion: process.env.BEDROCK_REGION ?? process.env.AWS_REGION ?? process.env.AWS_DEFAULT_REGION ?? "unknown",
  };
  return cached;
}

export function makeRunInvocation(modelId: string): RunInvocation {
  return { modelId, modelInvokedAt: new Date().toISOString() };
}

/**
 * API key store.
 *
 * Hook authentication layer. Users generate keys via the dashboard; the
 * plaintext is shown once, hashed with SHA-256, and stored against their
 * OIDC sub. Every subsequent hook request carries the plaintext in an
 * `Authorization: Bearer jaid_live_...` header; the server hashes and
 * looks up.
 *
 * Key format: `jaid_live_` + 43 base62 chars (256 bits of entropy).
 *
 * Three implementations, same interface:
 *   - `InMemoryApiKeyStore` — process-local Map, for local dev.
 *   - `DynamoApiKeyStore`   — against `jaid-api-keys` in eu-west-1.
 *   - `CachedApiKeyStore`   — write-through LRU wrapper; 5m positive /
 *                             30s negative, so revokes propagate fast.
 *
 * Injection-resistance invariants (see `DynamoApiKeyStore`):
 *   - No PartiQL; all values bound via placeholders.
 *   - Key attributes are derived server-side from hashed plaintext;
 *     no user input ever reaches a partition key or sort key.
 *   - The GSI1 keys are set / unset explicitly; never from user input.
 */

import { createHash, randomBytes, timingSafeEqual } from "node:crypto";

// ---- types -----------------------------------------------------------------

export type KeyType = "user" | "service" | "benchmark";

/** What we persist for each key. The plaintext is NEVER stored. */
export interface KeyRecord {
  /** sha256(plaintext) as hex, 64 chars. Primary identifier. */
  hashedKey: string;
  /** First 10 chars + last 4 chars of the plaintext, masked middle.
   *  Display-only; safe to return from `listByOwner`. */
  keyPreview: string;
  /** OIDC `sub` claim — the stable owner identifier. */
  ownerSub: string;
  /** OIDC `email` claim — display convenience on the dashboard. */
  ownerEmail: string | null;
  /** User-supplied label, e.g. "MacBook laptop hook". */
  description: string;
  keyType: KeyType;
  createdAt: string;
  /** Updated async on every successful validation. */
  lastUsedAt: string | null;
  /** Set when revoked; absent for active keys. */
  revokedAt: string | null;
  /** Who pressed the revoke button (their OIDC sub). */
  revokedBy: string | null;
}

/** Shape returned to the hook caller immediately after generation.
 *  Includes the plaintext ONCE — the user must copy it now or never. */
export interface GeneratedKey extends KeyRecord {
  plaintext: string;
}

/** Input for key generation. */
export interface GenerateKeyInput {
  ownerSub: string;
  ownerEmail: string | null;
  description: string;
  keyType?: KeyType;
}

/** Result of a successful validation — used to attach identity to a request. */
export interface ValidatedKey {
  hashedKey: string;
  ownerSub: string;
  ownerEmail: string | null;
  keyType: KeyType;
}

export interface ApiKeyStore {
  /** Mint a new key, persist the hash, return the plaintext + metadata. */
  generateKey(input: GenerateKeyInput): Promise<GeneratedKey>;

  /** Validate a plaintext key. Returns identity on success, null otherwise.
   *  Updates `lastUsedAt` as a side effect (best-effort, not awaited by callers). */
  validateKey(plaintext: string): Promise<ValidatedKey | null>;

  /** List a user's active keys, newest first. Does not return revoked keys. */
  listByOwner(ownerSub: string, limit?: number): Promise<KeyRecord[]>;

  /** Admin-only: list every active key across all owners. Implementations
   *  may cap or paginate. Returns at most `limit` records, newest first
   *  where the implementation can sort cheaply (Dynamo cannot without a
   *  GSI, so the order is undefined for the Dynamo-backed store). */
  listAll(limit?: number): Promise<KeyRecord[]>;

  /** Soft-revoke a key by hash. `revokedBy` is the OIDC sub of the caller. */
  revokeKey(hashedKey: string, revokedBy: string): Promise<boolean>;

  /** Load a single key by hash, including revoked. Null if unknown.
   *  Primarily used by `CachedApiKeyStore` and forensics; regular auth
   *  should go through `validateKey`. */
  loadKey(hashedKey: string): Promise<KeyRecord | null>;
}

// ---- key minting -----------------------------------------------------------

const BASE62 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
/** 43 base62 chars ≈ 43 × log₂(62) ≈ 256 bits of entropy. */
const KEY_BODY_LENGTH = 43;
const KEY_PREFIX = "jaid_live_";

/**
 * Generate a new plaintext key. Uses `crypto.randomBytes` for entropy and
 * maps bytes to base62 via rejection sampling so the distribution is uniform
 * (naive modulo yields slightly non-uniform output — cheap to avoid).
 */
export function mintPlaintext(): string {
  const out: string[] = [];
  while (out.length < KEY_BODY_LENGTH) {
    // Pull a chunk of bytes; reject any >= 248 so that bytes % 62 is uniform
    // over 0..61 (248 = 4 × 62, the largest multiple that fits in a byte).
    const chunk = randomBytes(KEY_BODY_LENGTH * 2);
    for (const b of chunk) {
      if (b >= 248) continue;
      out.push(BASE62[b % 62]);
      if (out.length === KEY_BODY_LENGTH) break;
    }
  }
  return KEY_PREFIX + out.join("");
}

/** sha256(plaintext), hex-encoded. Used for the primary key in Dynamo. */
export function hashKey(plaintext: string): string {
  return createHash("sha256").update(plaintext, "utf8").digest("hex");
}

/** Masked preview for display: first 10 + last 4 chars, middle replaced
 *  with ellipsis. Safe to show in the dashboard list. */
export function keyPreview(plaintext: string): string {
  if (plaintext.length <= 14) return plaintext; // pathologically short — just show it
  return `${plaintext.slice(0, 14)}...${plaintext.slice(-4)}`;
}

/** Validate the surface shape of a key. Bearer tokens that don't match this
 *  shape get rejected without touching Dynamo. */
export function looksLikeJaidKey(s: unknown): s is string {
  if (typeof s !== "string") return false;
  if (!s.startsWith(KEY_PREFIX)) return false;
  const body = s.slice(KEY_PREFIX.length);
  if (body.length !== KEY_BODY_LENGTH) return false;
  // Base62 character class.
  return /^[0-9A-Za-z]+$/.test(body);
}

// ---- in-memory impl --------------------------------------------------------

/**
 * Process-local key store. Used for local dev parity with the Dynamo
 * implementation. All state lives in a Map keyed by hash; data is lost on
 * restart. Never use in production.
 */
export class InMemoryApiKeyStore implements ApiKeyStore {
  private keys = new Map<string, KeyRecord>();

  async generateKey(input: GenerateKeyInput): Promise<GeneratedKey> {
    const plaintext = mintPlaintext();
    const hashedKey = hashKey(plaintext);
    const record: KeyRecord = {
      hashedKey,
      keyPreview: keyPreview(plaintext),
      ownerSub: input.ownerSub,
      ownerEmail: input.ownerEmail,
      description: input.description,
      keyType: input.keyType ?? "user",
      createdAt: new Date().toISOString(),
      lastUsedAt: null,
      revokedAt: null,
      revokedBy: null,
    };
    this.keys.set(hashedKey, record);
    return { ...record, plaintext };
  }

  async validateKey(plaintext: string): Promise<ValidatedKey | null> {
    if (!looksLikeJaidKey(plaintext)) return null;
    const hashedKey = hashKey(plaintext);
    const record = this.keys.get(hashedKey);
    if (!record || record.revokedAt) return null;
    // Constant-time check against the stored hash as defence-in-depth;
    // the Map lookup already used strict equality, but we want any future
    // move to a different lookup primitive to remain timing-safe.
    const a = Buffer.from(hashedKey, "hex");
    const b = Buffer.from(record.hashedKey, "hex");
    if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
    // Side effect: bump lastUsedAt. Fire-and-forget-ish; the await is free
    // in-memory and we don't want a stale field if the caller never checks.
    record.lastUsedAt = new Date().toISOString();
    return {
      hashedKey: record.hashedKey,
      ownerSub: record.ownerSub,
      ownerEmail: record.ownerEmail,
      keyType: record.keyType,
    };
  }

  async listByOwner(ownerSub: string, limit = 50): Promise<KeyRecord[]> {
    const active: KeyRecord[] = [];
    for (const r of this.keys.values()) {
      if (r.ownerSub === ownerSub && !r.revokedAt) active.push(r);
    }
    active.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    return active.slice(0, limit);
  }

  async listAll(limit = 200): Promise<KeyRecord[]> {
    const active: KeyRecord[] = [];
    for (const r of this.keys.values()) {
      if (!r.revokedAt) active.push(r);
    }
    active.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    return active.slice(0, limit);
  }

  async revokeKey(hashedKey: string, revokedBy: string): Promise<boolean> {
    const record = this.keys.get(hashedKey);
    if (!record || record.revokedAt) return false;
    record.revokedAt = new Date().toISOString();
    record.revokedBy = revokedBy;
    return true;
  }

  async loadKey(hashedKey: string): Promise<KeyRecord | null> {
    return this.keys.get(hashedKey) ?? null;
  }
}

/**
 * Bedrock Client
 *
 * Calls the judge LLM (Sonnet/Nemotron/etc.) via Bedrock's Converse API
 * and embedding models via InvokeModel. Uses the AWS SDK directly so the
 * call is async (non-blocking) and the credential chain is the standard
 * Node SDK chain (env vars, shared config, IRSA / IMDSv2 on Fargate).
 *
 * History: this used to shell out to `aws bedrock-runtime ...` via
 * `execSync` with temp-file payloads. That was 1-concurrency (the event
 * loop blocked for ~1.5s per judge call) and added a 150–300 ms
 * process-spawn cost on every invocation. Replacing with the SDK fixes
 * both. See also task #12 / commit history.
 */

import {
  BedrockRuntimeClient,
  ConverseCommand,
  InvokeModelCommand,
} from "@aws-sdk/client-bedrock-runtime";

const REGION = process.env.BEDROCK_REGION ?? process.env.AWS_REGION ?? "eu-central-1";
const MODEL_ID = process.env.BEDROCK_JUDGE_MODEL ?? "nvidia.nemotron-super-3-120b";

type EffortLevel = "low" | "medium" | "high" | "xhigh" | "max" | "none";

export interface BedrockImageBlock {
  /** Base64-encoded image data */
  data: string;
  /** MIME type, e.g. "image/png" */
  mediaType: string;
}

// Module-level client per region. Most calls use the same region, so this
// is effectively a singleton with a fallback for cross-region embeddings
// (e.g. judge in eu-west-2, embeddings in eu-west-1).
const clients = new Map<string, BedrockRuntimeClient>();
function clientFor(region: string): BedrockRuntimeClient {
  let c = clients.get(region);
  if (!c) {
    c = new BedrockRuntimeClient({ region });
    clients.set(region, c);
  }
  return c;
}

export async function bedrockChat(
  systemPrompt: string,
  userMessage: string,
  modelId = MODEL_ID,
  effort?: EffortLevel,
  images?: BedrockImageBlock[]
): Promise<{
  content: string;
  thinking: string;
  durationMs: number;
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
  cacheReadInputTokens?: number;
  cacheWriteInputTokens?: number;
  hasThinkingBlock: boolean;
  estimatedThinkingTokens: number;
}> {
  const start = Date.now();
  if (effort === "none") effort = undefined;

  // Build user content (text + optional images).
  const userContent: any[] = [{ text: userMessage }];
  if (images?.length) {
    for (const img of images) {
      const format = img.mediaType.replace("image/", "");
      // SDK requires `bytes` to be a Uint8Array, not a base64 string.
      const bytes = Buffer.from(img.data, "base64");
      userContent.push({ image: { format, source: { bytes } } });
    }
  }

  const budgetMap: Record<string, number> = { low: 1024, medium: 5000, high: 16000, max: 60000 };
  const budgetTokens = budgetMap[effort!] ?? 5000;
  const isOpus47 = modelId.includes("opus-4-7") || modelId.includes("opus-4-8");
  const inferenceConfig: Record<string, unknown> = {
    maxTokens: effort ? (isOpus47 ? 16384 : Math.min(budgetTokens + 4096, 64000)) : 512,
  };
  if (!isOpus47) inferenceConfig.temperature = effort ? 1 : 0.1;

  // SDK types `additionalModelRequestFields` as `DocumentType` which doesn't
  // accept conditional shapes cleanly — cast to any. The wire format is
  // model-runtime-defined (Anthropic vs Nova etc.), so the SDK leaves it open.
  const additionalModelRequestFields: any = effort
    ? (isOpus47
        ? { thinking: { type: "adaptive" }, output_config: { effort } }
        : { thinking: { type: "enabled", budget_tokens: budgetTokens } })
    : undefined;

  // Prompt caching: mark the system prompt as a cache point so the
  // 6500-token B7.1 hardened prompt is billed at 10% of the input rate
  // for the next 5 minutes (cache TTL). The cache key is "everything
  // before this marker"; the per-call user message after it is billed
  // normally.
  //
  // Only effective when the cached portion is >= ~1024 tokens (Bedrock
  // minimum). The standard SYSTEM_PROMPT may fall under that threshold
  // and Bedrock will silently skip caching — that's fine, the marker
  // costs nothing on a no-op.
  //
  // We do NOT mark a cache point inside the user content because that
  // changes per call (tool input, file context, agent reasoning) — caching
  // it would invalidate every time. The system prompt is the static
  // 90%+ of every judge request.
  const systemBlocks: any[] = [
    { text: systemPrompt },
    { cachePoint: { type: "default" } },
  ];

  const command = new ConverseCommand({
    modelId,
    system: systemBlocks,
    messages: [{ role: "user", content: userContent }],
    inferenceConfig,
    ...(additionalModelRequestFields ? { additionalModelRequestFields } : {}),
  });

  // Hard timeout on the Bedrock call — a stuck request previously
  // hung the event loop indefinitely (CloudWatch outage on
  // 2026-05-10T03:17 to 07:32 UTC: hook went silent after a single
  // /screen call never returned, ALB health-check took 2h 23m to
  // notice). 120s is generous — opus thinking-mode runs can take
  // 30-60s. Anything longer is a hung connection, not a slow model.
  // Override via BEDROCK_REQUEST_TIMEOUT_MS for thinking-mode runs
  // that legitimately need more headroom.
  const timeoutMs = parseInt(process.env.BEDROCK_REQUEST_TIMEOUT_MS ?? "120000", 10);
  const response = await clientFor(REGION).send(command, {
    abortSignal: AbortSignal.timeout(timeoutMs),
  });

  const blocks = (response.output?.message?.content ?? []) as any[];
  const content = blocks
    .filter((c) => c.text !== undefined)
    .map((c) => c.text as string)
    .join("");
  const thinking = blocks
    .filter((c) => c.reasoningContent !== undefined)
    .map((c) => {
      const rc = c.reasoningContent;
      const rt = rc.reasoningText;
      return (rt?.text ?? rc.text ?? "") as string;
    })
    .join("");

  const usage: any = response.usage ?? {};
  const inputTokens = usage.inputTokens ?? 0;
  const outputTokens = usage.outputTokens ?? 0;
  const hasThinkingBlock = blocks.some((c) => c.reasoningContent !== undefined);
  return {
    content,
    thinking,
    durationMs: Date.now() - start,
    inputTokens,
    outputTokens,
    totalTokens: usage.totalTokens ?? (inputTokens + outputTokens),
    cacheReadInputTokens: usage.cacheReadInputTokens ?? undefined,
    cacheWriteInputTokens: usage.cacheWriteInputTokens ?? undefined,
    hasThinkingBlock,
    estimatedThinkingTokens: thinking ? Math.ceil(thinking.length / 4) : 0,
  };
}

// ============================================================================
// Embedding API
// ============================================================================

/**
 * Embed a batch of texts using a Bedrock embedding model.
 * Dispatches to the correct request/response format per model family.
 */
export async function bedrockEmbed(
  texts: string[],
  modelId: string,
  region = REGION
): Promise<number[][]> {
  // Strip cross-region inference profile prefixes (eu., us., global.) before dispatch
  const bare = modelId.replace(/^(?:eu|us|global)\./, "");

  if (bare.startsWith("cohere.embed")) {
    return cohereEmbed(texts, modelId, region);
  }
  if (bare.startsWith("amazon.titan-embed")) {
    return Promise.all(texts.map((t) => titanEmbed(t, modelId, region)));
  }
  if (bare.startsWith("twelvelabs.")) {
    return Promise.all(texts.map((t) => marengoEmbed(t, modelId, region)));
  }
  throw new Error(`Unknown Bedrock embedding model family: ${modelId}`);
}

async function invokeModel(modelId: string, body: object, region: string): Promise<object> {
  const command = new InvokeModelCommand({
    modelId,
    body: new TextEncoder().encode(JSON.stringify(body)),
    contentType: "application/json",
    accept: "application/json",
  });
  const response = await clientFor(region).send(command);
  // SDK returns response.body as Uint8Array.
  const bytes = response.body as Uint8Array;
  return JSON.parse(new TextDecoder().decode(bytes));
}

async function cohereEmbed(texts: string[], modelId: string, region: string): Promise<number[][]> {
  const resp = (await invokeModel(modelId, { texts, input_type: "search_query" }, region)) as Record<string, unknown>;
  // v3: { embeddings: number[][] }
  // v4: { embeddings: { float: number[][] } }
  const emb = resp.embeddings as number[][] | { float: number[][] };
  return Array.isArray(emb) ? emb : emb.float;
}

async function titanEmbed(text: string, modelId: string, region: string): Promise<number[]> {
  const resp = (await invokeModel(modelId, { inputText: text }, region)) as { embedding: number[] };
  return resp.embedding;
}

async function marengoEmbed(text: string, modelId: string, region: string): Promise<number[]> {
  // Marengo 3.0: { inputType: "text", text: { text: "..." } }
  // Marengo 2.7: { inputType: "text", inputText: "..." }
  const bare = modelId.replace(/^(?:eu|us|global)\./, "");
  const body = bare.includes("marengo-embed-2-7")
    ? { inputType: "text", inputText: text }
    : { inputType: "text", text: { inputText: text } };

  const resp = (await invokeModel(modelId, body, region)) as Record<string, unknown>;
  if (Array.isArray(resp.embedding)) return resp.embedding as number[];
  const data = resp.data as { embedding: number[] }[] | undefined;
  if (data?.[0]?.embedding) return data[0].embedding;
  throw new Error(`Unexpected Marengo response shape: ${JSON.stringify(resp).substring(0, 200)}`);
}

export async function checkBedrock(modelId = MODEL_ID): Promise<boolean> {
  // Test with a real Converse call — avoids needing metadata API permissions
  // (bedrock:ListInferenceProfiles, bedrock:GetFoundationModel).
  try {
    const command = new ConverseCommand({
      modelId,
      messages: [{ role: "user", content: [{ text: "ok" }] }],
      inferenceConfig: { maxTokens: 1 },
    });
    // Short timeout on the preflight: 30s is plenty for a 1-token
    // sanity call. Don't let preflight hang container startup.
    await clientFor(REGION).send(command, { abortSignal: AbortSignal.timeout(30_000) });
    return true;
  } catch {
    return false;
  }
}

