  if (now - lastDropReport < DROP_REPORT_INTERVAL_MS) return;
  // Use process.stderr.write directly so we don't recurse through the
  // console override.
  process.stderr.write(`[logger] dropped ${droppedLines} log lines (queue full)\n`);
