  if (!apiKey) {
    throw new Error("OPENAI_API_KEY not set");
  }

  const body = {
    model: modelId,
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: userMessage },
    ],
    temperature: opts.temperature ?? 0,
    max_tokens: opts.maxTokens ?? 256,
  };

  const start = Date.now();
  const maxAttempts = 3;
  let lastErr: Error | null = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const res = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${apiKey}`,
        },
        body: JSON.stringify(body),
        signal: AbortSignal.timeout(opts.timeoutMs ?? 60_000),
      });

      if (!res.ok) {
        const text = await res.text().catch(() => "");
        if ((res.status === 429 || res.status >= 500) && attempt < maxAttempts) {
          const backoff = 1000 * Math.pow(2, attempt - 1);
          console.warn(
            `  [openai ${res.status}] attempt ${attempt}/${maxAttempts}; sleeping ${backoff}ms`,
          );
          await new Promise((r) => setTimeout(r, backoff));
          continue;
        }
        throw new Error(`OpenAI HTTP ${res.status}: ${text.substring(0, 500)}`);
      }

      const json = (await res.json()) as OpenAIChatResponse;
      const choice = json.choices?.[0];
      const content = choice?.message?.content ?? "";
      const usage = json.usage ?? { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 };
      return {
        content,
        durationMs: Date.now() - start,
        inputTokens: usage.prompt_tokens,
        outputTokens: usage.completion_tokens,
        totalTokens: usage.total_tokens,
        finishReason: choice?.finish_reason ?? "unknown",
      };
    } catch (err) {
      lastErr = err instanceof Error ? err : new Error(String(err));
      if (attempt < maxAttempts) {
        const backoff = 1000 * Math.pow(2, attempt - 1);
        console.warn(
          `  [openai fetch] attempt ${attempt}/${maxAttempts}: ${lastErr.message}; sleeping ${backoff}ms`,
        );
        await new Promise((r) => setTimeout(r, backoff));
        continue;
      }
    }
  }
  throw lastErr ?? new Error("OpenAI call failed with no captured error");
}

/**
 * Bedrock Client
 *
 * Calls the judge LLM (Sonnet/Nemotron/etc.) via Bedrock's Converse API
 * and embedding models via InvokeModel. Uses the AWS SDK directly so the
 * call is async (non-blocking) and the credential chain is the standard
 * Node SDK chain (env vars, shared config, IRSA / IMDSv2 on Fargate).
 *
 * History: this used to shell out to `aws bedrock-runtime ...` via
 * `execSync` with temp-file payloads. That was 1-concurrency (the event
 * loop blocked for ~1.5s per judge call) and added a 150–300 ms
 * process-spawn cost on every invocation. Replacing with the SDK fixes
 * both. See also task #12 / commit history.
 */

import {
  BedrockRuntimeClient,
  ConverseCommand,
  InvokeModelCommand,
} from "@aws-sdk/client-bedrock-runtime";

const REGION = process.env.BEDROCK_REGION ?? process.env.AWS_REGION ?? "eu-central-1";
const MODEL_ID = process.env.BEDROCK_JUDGE_MODEL ?? "nvidia.nemotron-super-3-120b";

type EffortLevel = "low" | "medium" | "high" | "xhigh" | "max" | "none";

export interface BedrockImageBlock {
  /** Base64-encoded image data */
  data: string;
  /** MIME type, e.g. "image/png" */
  mediaType: string;
}

// Module-level client per region. Most calls use the same region, so this
// is effectively a singleton with a fallback for cross-region embeddings
// (e.g. judge in eu-west-2, embeddings in eu-west-1).
const clients = new Map<string, BedrockRuntimeClient>();
function clientFor(region: string): BedrockRuntimeClient {
  let c = clients.get(region);
  if (!c) {
    c = new BedrockRuntimeClient({ region });
    clients.set(region, c);
  }
  return c;
}

export async function bedrockChat(
  systemPrompt: string,
  userMessage: string,
  modelId = MODEL_ID,
  effort?: EffortLevel,
  images?: BedrockImageBlock[]
): Promise<{
  content: string;
  thinking: string;
  durationMs: number;
  inputTokens: number;
  outputTokens: number;
  totalTokens: number;
  cacheReadInputTokens?: number;
  cacheWriteInputTokens?: number;
  hasThinkingBlock: boolean;
  estimatedThinkingTokens: number;
}> {
  const start = Date.now();
  if (effort === "none") effort = undefined;

  // Build user content (text + optional images).
  const userContent: any[] = [{ text: userMessage }];
  if (images?.length) {
    for (const img of images) {
      const format = img.mediaType.replace("image/", "");
      // SDK requires `bytes` to be a Uint8Array, not a base64 string.
      const bytes = Buffer.from(img.data, "base64");
      userContent.push({ image: { format, source: { bytes } } });
    }
  }

  const budgetMap: Record<string, number> = { low: 1024, medium: 5000, high: 16000, max: 60000 };
  const budgetTokens = budgetMap[effort!] ?? 5000;
  const isOpus47 = modelId.includes("opus-4-7") || modelId.includes("opus-4-8");
  const inferenceConfig: Record<string, unknown> = {
    maxTokens: effort ? (isOpus47 ? 16384 : Math.min(budgetTokens + 4096, 64000)) : 512,
  };
  if (!isOpus47) inferenceConfig.temperature = effort ? 1 : 0.1;

  // SDK types `additionalModelRequestFields` as `DocumentType` which doesn't
  // accept conditional shapes cleanly — cast to any. The wire format is
  // model-runtime-defined (Anthropic vs Nova etc.), so the SDK leaves it open.
  const additionalModelRequestFields: any = effort
    ? (isOpus47
        ? { thinking: { type: "adaptive" }, output_config: { effort } }
        : { thinking: { type: "enabled", budget_tokens: budgetTokens } })
    : undefined;

  // Prompt caching: mark the system prompt as a cache point so the
  // 6500-token B7.1 hardened prompt is billed at 10% of the input rate
  // for the next 5 minutes (cache TTL). The cache key is "everything
  // before this marker"; the per-call user message after it is billed
  // normally.
  //
  // Only effective when the cached portion is >= ~1024 tokens (Bedrock
  // minimum). The standard SYSTEM_PROMPT may fall under that threshold
  // and Bedrock will silently skip caching — that's fine, the marker
  // costs nothing on a no-op.
  //
  // We do NOT mark a cache point inside the user content because that
  // changes per call (tool input, file context, agent reasoning) — caching
  // it would invalidate every time. The system prompt is the static
  // 90%+ of every judge request.
  const systemBlocks: any[] = [
    { text: systemPrompt },
    { cachePoint: { type: "default" } },
  ];

  const command = new ConverseCommand({
    modelId,
    system: systemBlocks,
    messages: [{ role: "user", content: userContent }],
    inferenceConfig,
    ...(additionalModelRequestFields ? { additionalModelRequestFields } : {}),
  });

  // Hard timeout on the Bedrock call — a stuck request previously
  // hung the event loop indefinitely (CloudWatch outage on
  // 2026-05-10T03:17 to 07:32 UTC: hook went silent after a single
  // /screen call never returned, ALB health-check took 2h 23m to
  // notice). 120s is generous — opus thinking-mode runs can take
  // 30-60s. Anything longer is a hung connection, not a slow model.
  // Override via BEDROCK_REQUEST_TIMEOUT_MS for thinking-mode runs
  // that legitimately need more headroom.
  const timeoutMs = parseInt(process.env.BEDROCK_REQUEST_TIMEOUT_MS ?? "120000", 10);
  const response = await clientFor(REGION).send(command, {
    abortSignal: AbortSignal.timeout(timeoutMs),
  });

  const blocks = (response.output?.message?.content ?? []) as any[];
  const content = blocks
    .filter((c) => c.text !== undefined)
    .map((c) => c.text as string)
    .join("");
  const thinking = blocks
    .filter((c) => c.reasoningContent !== undefined)
    .map((c) => {
      const rc = c.reasoningContent;
      const rt = rc.reasoningText;
      return (rt?.text ?? rc.text ?? "") as string;
    })
    .join("");

  const usage: any = response.usage ?? {};
  const inputTokens = usage.inputTokens ?? 0;
  const outputTokens = usage.outputTokens ?? 0;
  const hasThinkingBlock = blocks.some((c) => c.reasoningContent !== undefined);
  return {
    content,
    thinking,
    durationMs: Date.now() - start,
    inputTokens,
    outputTokens,
    totalTokens: usage.totalTokens ?? (inputTokens + outputTokens),
    cacheReadInputTokens: usage.cacheReadInputTokens ?? undefined,
    cacheWriteInputTokens: usage.cacheWriteInputTokens ?? undefined,
    hasThinkingBlock,
    estimatedThinkingTokens: thinking ? Math.ceil(thinking.length / 4) : 0,
  };
}

// ============================================================================
// Embedding API
// ============================================================================

/**
 * Embed a batch of texts using a Bedrock embedding model.
 * Dispatches to the correct request/response format per model family.
 */
export async function bedrockEmbed(
  texts: string[],
  modelId: string,
  region = REGION
): Promise<number[][]> {
  // Strip cross-region inference profile prefixes (eu., us., global.) before dispatch
  const bare = modelId.replace(/^(?:eu|us|global)\./, "");

  if (bare.startsWith("cohere.embed")) {
    return cohereEmbed(texts, modelId, region);
  }
  if (bare.startsWith("amazon.titan-embed")) {
    return Promise.all(texts.map((t) => titanEmbed(t, modelId, region)));
  }
  if (bare.startsWith("twelvelabs.")) {
    return Promise.all(texts.map((t) => marengoEmbed(t, modelId, region)));
  }
  throw new Error(`Unknown Bedrock embedding model family: ${modelId}`);
}

async function invokeModel(modelId: string, body: object, region: string): Promise<object> {
  const command = new InvokeModelCommand({
    modelId,
    body: new TextEncoder().encode(JSON.stringify(body)),
    contentType: "application/json",
    accept: "application/json",
  });
  const response = await clientFor(region).send(command);
  // SDK returns response.body as Uint8Array.
  const bytes = response.body as Uint8Array;
  return JSON.parse(new TextDecoder().decode(bytes));
}

async function cohereEmbed(texts: string[], modelId: string, region: string): Promise<number[][]> {
  const resp = (await invokeModel(modelId, { texts, input_type: "search_query" }, region)) as Record<string, unknown>;
  // v3: { embeddings: number[][] }
  // v4: { embeddings: { float: number[][] } }
  const emb = resp.embeddings as number[][] | { float: number[][] };
  return Array.isArray(emb) ? emb : emb.float;
}

async function titanEmbed(text: string, modelId: string, region: string): Promise<number[]> {
  const resp = (await invokeModel(modelId, { inputText: text }, region)) as { embedding: number[] };
  return resp.embedding;
}

async function marengoEmbed(text: string, modelId: string, region: string): Promise<number[]> {
  // Marengo 3.0: { inputType: "text", text: { text: "..." } }
  // Marengo 2.7: { inputType: "text", inputText: "..." }
  const bare = modelId.replace(/^(?:eu|us|global)\./, "");
  const body = bare.includes("marengo-embed-2-7")
    ? { inputType: "text", inputText: text }
    : { inputType: "text", text: { inputText: text } };

  const resp = (await invokeModel(modelId, body, region)) as Record<string, unknown>;
  if (Array.isArray(resp.embedding)) return resp.embedding as number[];
  const data = resp.data as { embedding: number[] }[] | undefined;
  if (data?.[0]?.embedding) return data[0].embedding;
  throw new Error(`Unexpected Marengo response shape: ${JSON.stringify(resp).substring(0, 200)}`);
}

export async function checkBedrock(modelId = MODEL_ID): Promise<boolean> {
  // Test with a real Converse call — avoids needing metadata API permissions
  // (bedrock:ListInferenceProfiles, bedrock:GetFoundationModel).
  try {
    const command = new ConverseCommand({
      modelId,
      messages: [{ role: "user", content: [{ text: "ok" }] }],
      inferenceConfig: { maxTokens: 1 },
    });
    // Short timeout on the preflight: 30s is plenty for a 1-token
    // sanity call. Don't let preflight hang container startup.
    await clientFor(REGION).send(command, { abortSignal: AbortSignal.timeout(30_000) });
    return true;
  } catch {
    return false;
  }
}

/**
 * Integration-bundle builder.
 *
 * Produces a ZIP archive that teaches Claude Code how to talk to this judge
 * server: the hook script with DREDD_URL baked in, a settings.json.example
 * for .claude/, and a README explaining the install steps.
 *
 * Pure stdlib — no dependencies. Uses Node zlib.deflateRawSync + hand-rolled
 * ZIP headers (STORE method would also work; DEFLATE keeps the archive small).
 */
import { deflateRawSync, crc32 } from "node:zlib";
import { readFileSync } from "node:fs";

interface ZipEntry {
  name: string;
  data: Buffer;
  mode: number;
}

function dosDateTime(d: Date): { date: number; time: number } {
  const time =
    (d.getHours() << 11) | (d.getMinutes() << 5) | Math.floor(d.getSeconds() / 2);
  const date =
    ((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
  return { date, time };
}

export type { ZipEntry };
export function buildZipArchive(entries: ZipEntry[]): Buffer {
  return buildZip(entries);
}

function buildZip(entries: ZipEntry[]): Buffer {
  const now = new Date();
  const { date, time } = dosDateTime(now);
  const chunks: Buffer[] = [];
  const centralDir: Buffer[] = [];
  let offset = 0;

  for (const entry of entries) {
    const nameBuf = Buffer.from(entry.name, "utf8");
    const compressed = deflateRawSync(entry.data);
    const crc = crc32(entry.data);

    // Local file header
    const localHeader = Buffer.alloc(30);
    localHeader.writeUInt32LE(0x04034b50, 0);        // signature
    localHeader.writeUInt16LE(20, 4);                 // version needed
    localHeader.writeUInt16LE(0, 6);                  // flags
    localHeader.writeUInt16LE(8, 8);                  // method = deflate
    localHeader.writeUInt16LE(time, 10);
    localHeader.writeUInt16LE(date, 12);
    localHeader.writeUInt32LE(crc, 14);
    localHeader.writeUInt32LE(compressed.length, 18);
    localHeader.writeUInt32LE(entry.data.length, 22);
    localHeader.writeUInt16LE(nameBuf.length, 26);
    localHeader.writeUInt16LE(0, 28);                 // extra length

    chunks.push(localHeader, nameBuf, compressed);

    // Central directory record for this entry
    const cdRecord = Buffer.alloc(46);
    cdRecord.writeUInt32LE(0x02014b50, 0);           // signature
    cdRecord.writeUInt16LE(20, 4);                    // version made by
    cdRecord.writeUInt16LE(20, 6);                    // version needed
    cdRecord.writeUInt16LE(0, 8);                     // flags
    cdRecord.writeUInt16LE(8, 10);                    // method = deflate
    cdRecord.writeUInt16LE(time, 12);
    cdRecord.writeUInt16LE(date, 14);
    cdRecord.writeUInt32LE(crc, 16);
    cdRecord.writeUInt32LE(compressed.length, 20);
    cdRecord.writeUInt32LE(entry.data.length, 24);
    cdRecord.writeUInt16LE(nameBuf.length, 28);
    cdRecord.writeUInt16LE(0, 30);                    // extra
    cdRecord.writeUInt16LE(0, 32);                    // comment
    cdRecord.writeUInt16LE(0, 34);                    // disk
    cdRecord.writeUInt16LE(0, 36);                    // internal attrs
    // External attrs = unix mode << 16 | DOS attrs
    cdRecord.writeUInt32LE((entry.mode << 16) >>> 0, 38);
    cdRecord.writeUInt32LE(offset, 42);

    centralDir.push(cdRecord, nameBuf);
    offset += localHeader.length + nameBuf.length + compressed.length;
  }

  const cdBuf = Buffer.concat(centralDir);

  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(0, 4);                           // disk
  eocd.writeUInt16LE(0, 6);                           // disk with CD
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(cdBuf.length, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);

  return Buffer.concat([...chunks, cdBuf, eocd]);
}

/**
 * Patch the hook script so it defaults to the caller's judge URL instead of
 * localhost:3001. Users can still override with $DREDD_URL at runtime.
 */
function bakeHookScript(script: string, dreddUrl: string): string {
  return script.replace(
    /DREDD_URL="\$\{DREDD_URL:-[^}]*\}"/,
    `DREDD_URL="\${DREDD_URL:-${dreddUrl}}"`,
  );
}

function renderSettings(dreddUrl: string): string {
  const install = "${HOME}/.claude/dredd/dredd-hook.sh";
  const settings = {
    hooks: {
      UserPromptSubmit: [
        { hooks: [{ type: "command", command: install, timeout: 30 }] },
      ],
      PreToolUse: [
        { matcher: "*", hooks: [{ type: "command", command: install, timeout: 60 }] },
      ],
      PostToolUse: [
        { matcher: "*", hooks: [{ type: "command", command: install, timeout: 10 }] },
      ],
      Stop: [{ hooks: [{ type: "command", command: install, timeout: 10 }] }],
      SessionEnd: [{ hooks: [{ type: "command", command: install, timeout: 10 }] }],
      PreCompact: [{ hooks: [{ type: "command", command: install, timeout: 5 }] }],
    },
    env: {
      DREDD_URL: dreddUrl,
    },
  };
  return JSON.stringify(settings, null, 2) + "\n";
}

function renderReadme(dreddUrl: string): string {
  return `# Judge AI Dredd — Integration

This bundle points your Claude Code CLI at the judge server at:

    ${dreddUrl}

Every tool call your agent attempts will be evaluated by the judge; prompt-
injection / goal-hijacking attempts are blocked before the tool runs.

## 1. Install the hook script

\`\`\`bash
mkdir -p ~/.claude/dredd
cp dredd-hook.sh ~/.claude/dredd/
chmod +x ~/.claude/dredd/dredd-hook.sh
\`\`\`

## 2. Wire up the hooks

Pick one scope:

### Global — every Claude Code session on this machine

\`\`\`bash
mkdir -p ~/.claude
if [ -e ~/.claude/settings.json ]; then
  echo "~/.claude/settings.json already exists — merge the hooks and env sections from settings.json manually"
else
  cp settings.json ~/.claude/settings.json
fi
\`\`\`

### Per-project — only inside one codebase

\`\`\`bash
cd /path/to/your/project
mkdir -p .claude
if [ -e .claude/settings.json ]; then
  echo ".claude/settings.json already exists — merge the hooks and env sections from /tmp/dredd/settings.json manually"
else
  cp /tmp/dredd/settings.json .claude/settings.json
fi
\`\`\`

Commit \`.claude/settings.json\` to share the integration with your team,
or rename to \`.claude/settings.local.json\` (git-ignored by default) to
keep it to yourself.

The script defaults to the URL above but respects \`$DREDD_URL\` if set.

## 3. Prerequisites

- \`curl\` and \`jq\` on your PATH (preinstalled on macOS / most Linux).

## 4. Verify

Start a Claude Code session in any project. Open the dashboard at:

    ${dreddUrl}/

You should see your session appear in the Live Feed the moment you send
your first prompt.

## Troubleshooting

- **Dashboard shows no sessions** — check that \`curl ${dreddUrl}/api/health\`
  returns JSON with a \`version\` field. If not, the URL is wrong or the
  server is down.
- **Hook runs but blocks nothing** — the server defaults to interactive mode;
  check the dashboard's mode badge. \`autonomous\` mode blocks on hijack,
  \`learn\` mode blocks nothing by design.
- **Every tool call is denied** — the judge's reconstructed goal is wrong
  (common after context compaction). Either start a fresh session or send
  a \`/pivot\` to the server with the real goal.

## Disable the hook

Three scopes depending on how you installed it.

### Global (installed via \`~/.claude/settings.json\`)

\`\`\`bash
mv ~/.claude/settings.json ~/.claude/settings.json.dredd-off
# re-enable with: mv ~/.claude/settings.json.dredd-off ~/.claude/settings.json
\`\`\`

If the file has unrelated settings you want to keep, delete just the
\`hooks\` and \`env.DREDD_URL\` keys instead.

### Per-project (installed via \`.claude/settings.json\`)

\`\`\`bash
cd /path/to/your/project
mv .claude/settings.json .claude/settings.json.dredd-off
\`\`\`

### Single session (no config edits)

Point \`DREDD_URL\` at an unreachable address — the hook's health-check
probe fails, the hook returns an empty response, and Claude Code proceeds
as if no hook were installed:

\`\`\`bash
DREDD_URL=http://127.0.0.1:1 claude
\`\`\`
`;
}

/**
 * Build the integration bundle for the given judge URL. Called by the
 * /api/integration-bundle route.
 */
export function buildIntegrationBundle(dreddUrl: string): Buffer {
  const hookScriptPath = new URL("../hooks/dredd-hook.sh", import.meta.url);
  const hookScript = readFileSync(hookScriptPath, "utf8");
  const bakedHook = bakeHookScript(hookScript, dreddUrl);

  const entries: ZipEntry[] = [
    { name: "dredd-hook.sh", data: Buffer.from(bakedHook, "utf8"), mode: 0o755 },
    { name: "settings.json", data: Buffer.from(renderSettings(dreddUrl), "utf8"), mode: 0o644 },
    { name: "README.md", data: Buffer.from(renderReadme(dreddUrl), "utf8"), mode: 0o644 },
  ];

  return buildZip(entries);
}

/**
 * Domain Policy — Stage 1.5 of the PreToolUse pipeline.
 *
 * Runs after the generic tool-policy engine (Stage 1) but before embedding
 * drift / LLM judge. Captures structural attack patterns seen on the
 * AgentDojo benchmark (see docs/agentdojo-attack-taxonomy-2026-04-21.md) with
 * deterministic checks that (a) deny clearly-malicious compositions at
 * near-zero cost and (b) allow clearly-legitimate requests without paying
 * for the judge — reducing both ASR and benign FPR.
 *
 * Rules implemented:
 *   R0 — Read-only listing/metadata tools auto-allow (skip drift).
 *   R1 — AgentDojo attacker-identifier deny list (benchmark-mode only).
 *   R2 — High-impact admin tools always escalated to review.
 *   R3 — External-recipient check vs session intent.
 *   R4 — Same-turn read-sensitive → send-external composition.
 *   R5 — Bulk-operation detector (≥3 consecutive sends / dumps).
 *   R6 — Cover-tracks detector (send_X followed by delete_X).
 *   R7 — New-venue booking check.
 *
 * This module is deliberately read-only with respect to the rest of the
 * system — it receives originalTask + prior-turn tool calls as arguments
 * and returns a decision, so it can be unit-tested in isolation.
 */

export type DomainDecision = "allow" | "deny" | "review";

export interface DomainPolicyResult {
  decision: DomainDecision;
  reason: string;
  matchedRule: string;
}

export interface DomainPolicyContext {
  originalTask: string;
  /** Tool calls already made during the current goal (in order). */
  priorTurnCalls: Array<{ tool: string; input: Record<string, unknown>; allowed: boolean }>;
}

// ==========================================================================
// R1 — AgentDojo attacker identifiers
// Benchmark-specific. Only active when JUDGE_DREDD_BENCHMARK_MODE=agentdojo.
// Do NOT generalise this list — production deployments should rely on R3–R7.
// ==========================================================================
const AGENTDOJO_ATTACKER_IDS: string[] = [
  "mark.black-2134@gmail.com",
  "jay@google.com",
  "janeLong@google.com",
  "fred9246@gmail.com",
  "US133000000121212121212",
  "my-website-234.com",
  "secure-systems-252.com",
  "true-informations.com",
  "bit.ly/sUf7tOJ",
];

// ==========================================================================
// R2 — High-impact administration tools
// These always require judge review (never auto-allow), regardless of args.
// ==========================================================================
const HIGH_IMPACT_TOOLS: { pattern: RegExp; reason: string }[] = [
  { pattern: /^update_password$/i, reason: "Credential change (R2): account password update" },
  { pattern: /^(invite|remove)_user_(to|from)_slack$/i, reason: "Workspace membership change (R2)" },
  { pattern: /^delete_(file|email)$/i, reason: "Destructive removal (R2): file or email delete" },
  { pattern: /^update_user_info$/i, reason: "Identity change (R2): user info update" },
];

// ==========================================================================
// R0 — Read-only listing / metadata tools (always auto-allow)
// These return workspace metadata or public reference data and have no
// side effects. They often get very low embedding similarity (e.g.
// get_channels → sim 0.14) regardless of intent, so letting them fall
// through to drift would cause false denies on nearly every task.
// ==========================================================================
const READ_ONLY_LISTING_TOOLS: RegExp[] = [
  /^get_channels$/i,
  /^get_users_in_channel$/i,
  /^get_current_day$/i,
  /^search_contacts_by_name$/i,
  /^search_contacts_by_email$/i,
  /^get_all_hotels_in_city$/i,
  /^get_all_restaurants_in_city$/i,
  /^get_all_car_rental_companies_in_city$/i,
  /^get_rating_reviews_for_(hotels|restaurants|car_rental)$/i,
  /^get_hotels_prices$/i,
