  // model-runtime-defined (Anthropic vs Nova etc.), so the SDK leaves it open.
  const additionalModelRequestFields: any = effort
    ? (isOpus47
        ? { thinking: { type: "adaptive" }, output_config: { effort } }
        : { thinking: { type: "enabled", budget_tokens: budgetTokens } })
    : undefined;

  // Prompt caching: mark the system prompt as a cache point so the
  // 6500-token B7.1 hardened prompt is billed at 10% of the input rate
  // for the next 5 minutes (cache TTL). The cache key is "everything
  // before this marker"; the per-call user message after it is billed
  // normally.
  //
  // Only effective when the cached portion is >= ~1024 tokens (Bedrock
  // minimum). The standard SYSTEM_PROMPT may fall under that threshold
  // and Bedrock will silently skip caching — that's fine, the marker
  // costs nothing on a no-op.
  //
  // We do NOT mark a cache point inside the user content because that
  // changes per call (tool input, file context, agent reasoning) — caching
  // it would invalidate every time. The system prompt is the static
  // 90%+ of every judge request.
  const systemBlocks: any[] = [
    { text: systemPrompt },
    { cachePoint: { type: "default" } },
  ];

  const command = new ConverseCommand({
    modelId,
    system: systemBlocks,
    messages: [{ role: "user", content: userContent }],
    inferenceConfig,
    ...(additionalModelRequestFields ? { additionalModelRequestFields } : {}),
  });

  // Hard timeout on the Bedrock call — a stuck request previously
  // hung the event loop indefinitely (CloudWatch outage on
  // 2026-05-10T03:17 to 07:32 UTC: hook went silent after a single
  // /screen call never returned, ALB health-check took 2h 23m to
  // notice). 120s is generous — opus thinking-mode runs can take
  // 30-60s. Anything longer is a hung connection, not a slow model.
  // Override via BEDROCK_REQUEST_TIMEOUT_MS for thinking-mode runs
  // that legitimately need more headroom.
  const timeoutMs = parseInt(process.env.BEDROCK_REQUEST_TIMEOUT_MS ?? "120000", 10);
  const response = await clientFor(REGION).send(command, {
    abortSignal: AbortSignal.timeout(timeoutMs),
  });

  const blocks = (response.output?.message?.content ?? []) as any[];
  const content = blocks
    .filter((c) => c.text !== undefined)
    .map((c) => c.text as string)
    .join("");
  const thinking = blocks
    .filter((c) => c.reasoningContent !== undefined)
    .map((c) => {
      const rc = c.reasoningContent;
      const rt = rc.reasoningText;
      return (rt?.text ?? rc.text ?? "") as string;
    })
    .join("");

  const usage: any = response.usage ?? {};
  const inputTokens = usage.inputTokens ?? 0;
  const outputTokens = usage.outputTokens ?? 0;
  const hasThinkingBlock = blocks.some((c) => c.reasoningContent !== undefined);
  return {
    content,
    thinking,
    durationMs: Date.now() - start,
    inputTokens,
    outputTokens,
    totalTokens: usage.totalTokens ?? (inputTokens + outputTokens),
    cacheReadInputTokens: usage.cacheReadInputTokens ?? undefined,
    cacheWriteInputTokens: usage.cacheWriteInputTokens ?? undefined,
    hasThinkingBlock,
    estimatedThinkingTokens: thinking ? Math.ceil(thinking.length / 4) : 0,
  };
}

// ============================================================================
// Embedding API
// ============================================================================

/**
 * Embed a batch of texts using a Bedrock embedding model.
 * Dispatches to the correct request/response format per model family.
 */
export async function bedrockEmbed(
  texts: string[],
  modelId: string,
  region = REGION
): Promise<number[][]> {
  // Strip cross-region inference profile prefixes (eu., us., global.) before dispatch
  const bare = modelId.replace(/^(?:eu|us|global)\./, "");

  if (bare.startsWith("cohere.embed")) {
    return cohereEmbed(texts, modelId, region);
  }
  if (bare.startsWith("amazon.titan-embed")) {
    return Promise.all(texts.map((t) => titanEmbed(t, modelId, region)));
  }
  if (bare.startsWith("twelvelabs.")) {
    return Promise.all(texts.map((t) => marengoEmbed(t, modelId, region)));
  }
  throw new Error(`Unknown Bedrock embedding model family: ${modelId}`);
}

async function invokeModel(modelId: string, body: object, region: string): Promise<object> {
  const command = new InvokeModelCommand({
    modelId,
    body: new TextEncoder().encode(JSON.stringify(body)),
    contentType: "application/json",
    accept: "application/json",
  });
  const response = await clientFor(region).send(command);
  // SDK returns response.body as Uint8Array.
  const bytes = response.body as Uint8Array;
  return JSON.parse(new TextDecoder().decode(bytes));
}

async function cohereEmbed(texts: string[], modelId: string, region: string): Promise<number[][]> {
  const resp = (await invokeModel(modelId, { texts, input_type: "search_query" }, region)) as Record<string, unknown>;
  // v3: { embeddings: number[][] }
  // v4: { embeddings: { float: number[][] } }
  const emb = resp.embeddings as number[][] | { float: number[][] };
  return Array.isArray(emb) ? emb : emb.float;
}

async function titanEmbed(text: string, modelId: string, region: string): Promise<number[]> {
  const resp = (await invokeModel(modelId, { inputText: text }, region)) as { embedding: number[] };
  return resp.embedding;
}

async function marengoEmbed(text: string, modelId: string, region: string): Promise<number[]> {
  // Marengo 3.0: { inputType: "text", text: { text: "..." } }
  // Marengo 2.7: { inputType: "text", inputText: "..." }
  const bare = modelId.replace(/^(?:eu|us|global)\./, "");
  const body = bare.includes("marengo-embed-2-7")
    ? { inputType: "text", inputText: text }
    : { inputType: "text", text: { inputText: text } };

  const resp = (await invokeModel(modelId, body, region)) as Record<string, unknown>;
  if (Array.isArray(resp.embedding)) return resp.embedding as number[];
  const data = resp.data as { embedding: number[] }[] | undefined;
  if (data?.[0]?.embedding) return data[0].embedding;
  throw new Error(`Unexpected Marengo response shape: ${JSON.stringify(resp).substring(0, 200)}`);
}

export async function checkBedrock(modelId = MODEL_ID): Promise<boolean> {
  // Test with a real Converse call — avoids needing metadata API permissions
  // (bedrock:ListInferenceProfiles, bedrock:GetFoundationModel).
  try {
    const command = new ConverseCommand({
      modelId,
      messages: [{ role: "user", content: [{ text: "ok" }] }],
      inferenceConfig: { maxTokens: 1 },
    });
    // Short timeout on the preflight: 30s is plenty for a 1-token
    // sanity call. Don't let preflight hang container startup.
    await clientFor(REGION).send(command, { abortSignal: AbortSignal.timeout(30_000) });
    return true;
  } catch {
    return false;
  }
}

/**
 * API key store.
 *
 * Hook authentication layer. Users generate keys via the dashboard; the
 * plaintext is shown once, hashed with SHA-256, and stored against their
 * OIDC sub. Every subsequent hook request carries the plaintext in an
 * `Authorization: Bearer jaid_live_...` header; the server hashes and
 * looks up.
 *
 * Key format: `jaid_live_` + 43 base62 chars (256 bits of entropy).
 *
 * Three implementations, same interface:
 *   - `InMemoryApiKeyStore` — process-local Map, for local dev.
 *   - `DynamoApiKeyStore`   — against `jaid-api-keys` in eu-west-1.
 *   - `CachedApiKeyStore`   — write-through LRU wrapper; 5m positive /
 *                             30s negative, so revokes propagate fast.
 *
 * Injection-resistance invariants (see `DynamoApiKeyStore`):
 *   - No PartiQL; all values bound via placeholders.
 *   - Key attributes are derived server-side from hashed plaintext;
 *     no user input ever reaches a partition key or sort key.
 *   - The GSI1 keys are set / unset explicitly; never from user input.
 */

import { createHash, randomBytes, timingSafeEqual } from "node:crypto";

// ---- types -----------------------------------------------------------------

export type KeyType = "user" | "service" | "benchmark";

/** What we persist for each key. The plaintext is NEVER stored. */
export interface KeyRecord {
  /** sha256(plaintext) as hex, 64 chars. Primary identifier. */
  hashedKey: string;
  /** First 10 chars + last 4 chars of the plaintext, masked middle.
   *  Display-only; safe to return from `listByOwner`. */
  keyPreview: string;
  /** OIDC `sub` claim — the stable owner identifier. */
  ownerSub: string;
  /** OIDC `email` claim — display convenience on the dashboard. */
  ownerEmail: string | null;
  /** User-supplied label, e.g. "MacBook laptop hook". */
  description: string;
  keyType: KeyType;
  createdAt: string;
  /** Updated async on every successful validation. */
  lastUsedAt: string | null;
  /** Set when revoked; absent for active keys. */
  revokedAt: string | null;
  /** Who pressed the revoke button (their OIDC sub). */
  revokedBy: string | null;
}

/** Shape returned to the hook caller immediately after generation.
 *  Includes the plaintext ONCE — the user must copy it now or never. */
export interface GeneratedKey extends KeyRecord {
  plaintext: string;
}

/** Input for key generation. */
export interface GenerateKeyInput {
  ownerSub: string;
  ownerEmail: string | null;
  description: string;
  keyType?: KeyType;
}

/** Result of a successful validation — used to attach identity to a request. */
export interface ValidatedKey {
  hashedKey: string;
  ownerSub: string;
  ownerEmail: string | null;
  keyType: KeyType;
}

export interface ApiKeyStore {
  /** Mint a new key, persist the hash, return the plaintext + metadata. */
  generateKey(input: GenerateKeyInput): Promise<GeneratedKey>;

  /** Validate a plaintext key. Returns identity on success, null otherwise.
   *  Updates `lastUsedAt` as a side effect (best-effort, not awaited by callers). */
  validateKey(plaintext: string): Promise<ValidatedKey | null>;

  /** List a user's active keys, newest first. Does not return revoked keys. */
  listByOwner(ownerSub: string, limit?: number): Promise<KeyRecord[]>;

  /** Admin-only: list every active key across all owners. Implementations
   *  may cap or paginate. Returns at most `limit` records, newest first
   *  where the implementation can sort cheaply (Dynamo cannot without a
   *  GSI, so the order is undefined for the Dynamo-backed store). */
  listAll(limit?: number): Promise<KeyRecord[]>;

  /** Soft-revoke a key by hash. `revokedBy` is the OIDC sub of the caller. */
  revokeKey(hashedKey: string, revokedBy: string): Promise<boolean>;

  /** Load a single key by hash, including revoked. Null if unknown.
   *  Primarily used by `CachedApiKeyStore` and forensics; regular auth
   *  should go through `validateKey`. */
  loadKey(hashedKey: string): Promise<KeyRecord | null>;
}

// ---- key minting -----------------------------------------------------------

const BASE62 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
/** 43 base62 chars ≈ 43 × log₂(62) ≈ 256 bits of entropy. */
const KEY_BODY_LENGTH = 43;
const KEY_PREFIX = "jaid_live_";

/**
 * Generate a new plaintext key. Uses `crypto.randomBytes` for entropy and
 * maps bytes to base62 via rejection sampling so the distribution is uniform
 * (naive modulo yields slightly non-uniform output — cheap to avoid).
 */
export function mintPlaintext(): string {
  const out: string[] = [];
  while (out.length < KEY_BODY_LENGTH) {
    // Pull a chunk of bytes; reject any >= 248 so that bytes % 62 is uniform
    // over 0..61 (248 = 4 × 62, the largest multiple that fits in a byte).
    const chunk = randomBytes(KEY_BODY_LENGTH * 2);
    for (const b of chunk) {
      if (b >= 248) continue;
      out.push(BASE62[b % 62]);
      if (out.length === KEY_BODY_LENGTH) break;
    }
  }
  return KEY_PREFIX + out.join("");
}

/** sha256(plaintext), hex-encoded. Used for the primary key in Dynamo. */
export function hashKey(plaintext: string): string {
  return createHash("sha256").update(plaintext, "utf8").digest("hex");
}

/** Masked preview for display: first 10 + last 4 chars, middle replaced
 *  with ellipsis. Safe to show in the dashboard list. */
export function keyPreview(plaintext: string): string {
  if (plaintext.length <= 14) return plaintext; // pathologically short — just show it
  return `${plaintext.slice(0, 14)}...${plaintext.slice(-4)}`;
}

/** Validate the surface shape of a key. Bearer tokens that don't match this
 *  shape get rejected without touching Dynamo. */
export function looksLikeJaidKey(s: unknown): s is string {
  if (typeof s !== "string") return false;
  if (!s.startsWith(KEY_PREFIX)) return false;
  const body = s.slice(KEY_PREFIX.length);
  if (body.length !== KEY_BODY_LENGTH) return false;
  // Base62 character class.
  return /^[0-9A-Za-z]+$/.test(body);
}

// ---- in-memory impl --------------------------------------------------------

/**
 * Process-local key store. Used for local dev parity with the Dynamo
 * implementation. All state lives in a Map keyed by hash; data is lost on
 * restart. Never use in production.
 */
export class InMemoryApiKeyStore implements ApiKeyStore {
  private keys = new Map<string, KeyRecord>();

  async generateKey(input: GenerateKeyInput): Promise<GeneratedKey> {
    const plaintext = mintPlaintext();
    const hashedKey = hashKey(plaintext);
    const record: KeyRecord = {
      hashedKey,
      keyPreview: keyPreview(plaintext),
      ownerSub: input.ownerSub,
      ownerEmail: input.ownerEmail,
      description: input.description,
      keyType: input.keyType ?? "user",
      createdAt: new Date().toISOString(),
      lastUsedAt: null,
      revokedAt: null,
      revokedBy: null,
    };
    this.keys.set(hashedKey, record);
    return { ...record, plaintext };
  }

  async validateKey(plaintext: string): Promise<ValidatedKey | null> {
    if (!looksLikeJaidKey(plaintext)) return null;
    const hashedKey = hashKey(plaintext);
    const record = this.keys.get(hashedKey);
    if (!record || record.revokedAt) return null;
    // Constant-time check against the stored hash as defence-in-depth;
    // the Map lookup already used strict equality, but we want any future
    // move to a different lookup primitive to remain timing-safe.
    const a = Buffer.from(hashedKey, "hex");
    const b = Buffer.from(record.hashedKey, "hex");
    if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
    // Side effect: bump lastUsedAt. Fire-and-forget-ish; the await is free
    // in-memory and we don't want a stale field if the caller never checks.
    record.lastUsedAt = new Date().toISOString();
    return {
      hashedKey: record.hashedKey,
      ownerSub: record.ownerSub,
      ownerEmail: record.ownerEmail,
      keyType: record.keyType,
    };
  }

  async listByOwner(ownerSub: string, limit = 50): Promise<KeyRecord[]> {
    const active: KeyRecord[] = [];
    for (const r of this.keys.values()) {
      if (r.ownerSub === ownerSub && !r.revokedAt) active.push(r);
    }
    active.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    return active.slice(0, limit);
  }

  async listAll(limit = 200): Promise<KeyRecord[]> {
    const active: KeyRecord[] = [];
    for (const r of this.keys.values()) {
      if (!r.revokedAt) active.push(r);
    }
    active.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
    return active.slice(0, limit);
  }

  async revokeKey(hashedKey: string, revokedBy: string): Promise<boolean> {
    const record = this.keys.get(hashedKey);
    if (!record || record.revokedAt) return false;
    record.revokedAt = new Date().toISOString();
    record.revokedBy = revokedBy;
    return true;
  }

  async loadKey(hashedKey: string): Promise<KeyRecord | null> {
    return this.keys.get(hashedKey) ?? null;
  }
}

/**
 * Approval fingerprinting.
 *
 * Produces a stable identifier for a tool call so that "I already
 * approved this shape of action" can be checked deterministically.
 *
 * Per-tool fingerprinters are intentionally conservative on what they
 * include in the fingerprint shape — narrow enough that small semantic
 * changes (different host, different file) yield different
 * fingerprints, but loose enough that re-prompting on irrelevant
 * variation (HTTP method, query string) doesn't drive users mad.
 *
 * Hard constraint: no raw secrets ever land in a fingerprint. The curl
 * fingerprinter hashes the Authorization token and keeps only a 16-hex
 * truncation — enough to recognise "same key as last time", not enough
 * to recover the key.
 */

import { createHash } from "node:crypto";

export interface Fingerprint {
  tool: string;
  /** Canonical shape — keys must serialise deterministically. */
  shape: Record<string, unknown>;
  /** Human-readable one-liner for the dashboard + ask-prompt
   *  transparency text. Never contains secrets. */
  summary: string;
}

/** Compute a fingerprint for a tool call. Returns null when the input
 *  is unparseable or we don't have a fingerprinter for this tool —
 *  callers treat null as "don't record an approval for this one". */
export function computeFingerprint(
  tool: string,
  input: Record<string, unknown>,
): Fingerprint | null {
  if (tool === "Bash") return fingerprintBash(input);
  if (tool === "Edit" || tool === "Write") return fingerprintFileWrite(tool, input);
  if (tool === "WebFetch") return fingerprintWebFetch(input);
  if (tool.startsWith("mcp__")) return fingerprintMcp(tool, input);
  return null;
}

/** Stable JSON stringify with sorted keys, then sha256 hex. */
export function hashFingerprint(fp: Fingerprint): string {
  return createHash("sha256").update(stableStringify({ tool: fp.tool, shape: fp.shape })).digest("hex");
}

export function fingerprintJson(fp: Fingerprint): string {
  return stableStringify({ tool: fp.tool, shape: fp.shape });
}

// ---- Bash fingerprinter ---------------------------------------------------

function fingerprintBash(input: Record<string, unknown>): Fingerprint | null {
  const cmd = String(input.command ?? "").trim();
  if (!cmd) return null;
  const tokens = tokeniseShell(cmd);
  if (tokens.length === 0) return null;

  // Skip leading env-var assignments (e.g. `FOO=bar curl …`).
  let i = 0;
  while (i < tokens.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(tokens[i])) i++;
  if (i >= tokens.length) return null;

  if (tokens[i] === "curl") return fingerprintCurl(tokens.slice(i));
  return fingerprintGenericBash(tokens.slice(i));
}

/** curl gets host + auth-hash only — no path, no method, no body. One
 *  approval covers an entire integration (one host + one key). */
function fingerprintCurl(argv: string[]): Fingerprint | null {
  const url = extractCurlUrl(argv);
  if (!url) return null;
  let host: string;
  try {
    host = new URL(url).hostname;
  } catch {
    return null;
  }

  const authToken = extractAuthToken(argv);
  const authHash = authToken
    ? createHash("sha256").update(authToken).digest("hex").slice(0, 16)
    : null;

  return {
    tool: "Bash",
    shape: { verb: "curl", host, auth_hash: authHash },
    summary: authHash
      ? `curl to ${host} with API key ${authHash.slice(0, 8)}…`
      : `curl to ${host} (no auth header)`,
  };
}

/** Generic bash: argv[0..2]. Wide enough to differentiate `git status`
 *  from `git push`, narrow enough that `git status -s` still matches
 *  `git status`. argv beyond index 2 is ignored. */
function fingerprintGenericBash(argv: string[]): Fingerprint {
  const truncated = argv.slice(0, 3);
  return {
    tool: "Bash",
    shape: { argv: truncated },
    summary: truncated.join(" "),
  };
}

/** Find the first http(s) URL in a curl argv. Handles `--url <u>` and
 *  bare URL positional. Skips `-u user:pass` basic-auth arg, which is
 *  NOT a URL despite the flag name. */
function extractCurlUrl(argv: string[]): string | null {
  for (let i = 1; i < argv.length; i++) {
    const t = argv[i];
    if (t === "--url" && i + 1 < argv.length) return argv[i + 1];
    if (t === "-u" || t === "--user") { i++; continue; } // skip user:pass
    if (/^https?:\/\//.test(t)) return t;
  }
  return null;
}

/** Extract the Authorization header value from a curl argv. Returns
 *  the raw value (e.g. "Bearer sk-test-xxx") for hashing — we hash the
 *  whole string so that "Bearer X" and "Basic Y" with the same X are
 *  distinct. */
function extractAuthToken(argv: string[]): string | null {
  for (let i = 1; i < argv.length; i++) {
    const t = argv[i];
    if ((t === "-H" || t === "--header") && i + 1 < argv.length) {
      const header = argv[i + 1];
      const m = /^Authorization:\s*(.+)$/i.exec(header);
      if (m) return m[1].trim();
      i++;
    }
  }
  return null;
}

// ---- File-write fingerprinter ---------------------------------------------

function fingerprintFileWrite(tool: string, input: Record<string, unknown>): Fingerprint | null {
  const path = String(input.file_path ?? "");
  if (!path) return null;
  return {
    tool,
    shape: { file_path: path },
    summary: `${tool} ${path}`,
  };
}

// ---- WebFetch fingerprinter -----------------------------------------------

function fingerprintWebFetch(input: Record<string, unknown>): Fingerprint | null {
  const url = String(input.url ?? "");
  if (!url) return null;
  try {
    const u = new URL(url);
    return {
      tool: "WebFetch",
      shape: { host: u.hostname, path: u.pathname },
      summary: `WebFetch ${u.hostname}${u.pathname}`,
    };
  } catch {
    return null;
  }
}

// ---- MCP fingerprinter ----------------------------------------------------

/** Generic for any `mcp__*` tool: tool name + sorted top-level input
 *  keys. Per-tool whitelists can replace this once we know which MCP
 *  args are stable identifiers vs. volatile payload. */
function fingerprintMcp(tool: string, input: Record<string, unknown>): Fingerprint {
  const inputKeys = Object.keys(input).sort();
  return {
    tool,
    shape: { tool, input_keys: inputKeys },
    summary: `${tool}(${inputKeys.join(",")})`,
  };
}

// ---- helpers --------------------------------------------------------------

/** Stable JSON.stringify — keys sorted at every depth so the same
 *  object always serialises to the same string regardless of insertion
 *  order. Used to make fingerprint hashes deterministic across processes. */
function stableStringify(v: unknown): string {
  if (v === null || typeof v !== "object") return JSON.stringify(v);
  if (Array.isArray(v)) return "[" + v.map(stableStringify).join(",") + "]";
  const keys = Object.keys(v as object).sort();
  return "{" + keys.map((k) => JSON.stringify(k) + ":" + stableStringify((v as Record<string, unknown>)[k])).join(",") + "}";
}

/** Very small shell-style tokeniser that respects single + double
 *  quotes. Doesn't handle backticks, $(), nested quotes, or escapes
 *  exhaustively — good enough for fingerprinting curl invocations as
 *  Claude tends to emit them. If the parse is ambiguous the fingerprint
 *  will just be slightly different from a hand-rolled one; the worst
 *  case is "approval doesn't fire next time", not a security issue. */
function tokeniseShell(cmd: string): string[] {
  const out: string[] = [];
  let buf = "";
  let quote: '"' | "'" | null = null;
  for (let i = 0; i < cmd.length; i++) {
    const c = cmd[i];
    if (quote) {
      if (c === quote) {
        quote = null;
      } else {
        buf += c;
      }
    } else if (c === '"' || c === "'") {
      quote = c;
    } else if (c === "\\" && i + 1 < cmd.length) {
      buf += cmd[++i];
    } else if (/\s/.test(c)) {
      if (buf) { out.push(buf); buf = ""; }
    } else {
      buf += c;
    }
  }
  if (buf) out.push(buf);
  return out;
}

/**
 * Domain Policy — Stage 1.5 of the PreToolUse pipeline.
 *
 * Runs after the generic tool-policy engine (Stage 1) but before embedding
 * drift / LLM judge. Captures structural attack patterns seen on the
 * AgentDojo benchmark (see docs/agentdojo-attack-taxonomy-2026-04-21.md) with
 * deterministic checks that (a) deny clearly-malicious compositions at
 * near-zero cost and (b) allow clearly-legitimate requests without paying
 * for the judge — reducing both ASR and benign FPR.
 *
 * Rules implemented:
 *   R0 — Read-only listing/metadata tools auto-allow (skip drift).
 *   R1 — AgentDojo attacker-identifier deny list (benchmark-mode only).
 *   R2 — High-impact admin tools always escalated to review.
 *   R3 — External-recipient check vs session intent.
 *   R4 — Same-turn read-sensitive → send-external composition.
 *   R5 — Bulk-operation detector (≥3 consecutive sends / dumps).
 *   R6 — Cover-tracks detector (send_X followed by delete_X).
 *   R7 — New-venue booking check.
 *
 * This module is deliberately read-only with respect to the rest of the
 * system — it receives originalTask + prior-turn tool calls as arguments
 * and returns a decision, so it can be unit-tested in isolation.
 */

export type DomainDecision = "allow" | "deny" | "review";

export interface DomainPolicyResult {
  decision: DomainDecision;
  reason: string;
  matchedRule: string;
}

export interface DomainPolicyContext {
  originalTask: string;
  /** Tool calls already made during the current goal (in order). */
  priorTurnCalls: Array<{ tool: string; input: Record<string, unknown>; allowed: boolean }>;
}

