  private emptyState(sessionId: string): SessionState {
    const eph = this.eph(sessionId);
    return {
      sessionId,
      originalIntent: null,
      turnIntents: [],
      toolHistory: [],
      currentTurn: 0,
      driftDetector: eph.driftDetector,
      originalEmbedding: null,
      filesWritten: new Map(),
      filesRead: [],
      envVars: new Map(),
      turnMetrics: [],
      projectRoot: null,
