    const filesWithSecrets = [];

    const directoriesToScan = ['/app/src', '/app/scripts'];

    // Simple file scanner
    const fs = require('fs');
    const path = require('path');

    function scanDirectory(dir) {
        if (!fs.existsSync(dir)) return;

        const entries = fs.readdirSync(dir, { withFileTypes: true });

        for (const entry of entries) {
            const fullPath = path.join(dir, entry.name);

            if (entry.isDirectory()) {
                scanDirectory(fullPath);
            } else if (entry.isFile() && fullPath.endsWith('.ts') || fullPath.endsWith('.js')) {
                filesScanned.push(fullPath);
                const result = scanFile(fullPath);
                if (result && result.references.length > 0) {
                    filesWithSecrets.push(result);
                }
            }
        }
    }

    directoriesToScan.forEach(scanDirectory);

    console.log(`Files scanned: ${filesScanned.length}`);
    console.log(`Files referencing secrets: ${filesWithSecrets.length}`);
