        } else if (SEVERITY_ASSESSMENT.MEDIUM.includes(pattern.name)) {
            bySeverity.HIGH.push(pattern);
        } else if (SEVERITY_ASSESSMENT.LOW.includes(pattern.name)) {
            bySeverity.MEDIUM.push(pattern);
        } else {
            bySeverity.LOW.push(pattern);
        }
    }

