                console.log(`   Description: ${pattern.description}`);
                console.log(`   Location: ${pattern.location}`);
                console.log(`   Required: ${pattern.required ? '✅ Yes' : '❌ Optional'}`);
                console.log(`   Pattern: ${pattern.pattern.source.substring(0, 60)}...`);
